(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["rl"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-does-rlhf-scale-exploring-the-impact-2024"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-1\">一 · 一个夜间在线服务的现场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-2\">二 · 论文之前的主流做法：三段串行、批量为王</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-3\">三 · 奖励评估段的耦合代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-4\">四 · 过滤阈值：被当成后处理，其实是吞吐旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-5\">五 · 异步流水线与权重同步点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-6\">六 · 为什么非改不可：扩展性结论对栈设计的反向约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-7\">七 · 批同步屏障：旧 rollout 栈在长尾分布下的结构性失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-8\">八 · 先量清楚请求，再谈调度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-9\">九 · 并发与 SLO：两个约束互相挤压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-10\">十 · 批大小如何反向塑造负载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-11\">十一 · 长尾的两段耦合：生成拖一次，评估再拖一次</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-12\">十二 · 异步流水线与权重同步：负载形态的第三维</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-13\">十三 · 测量口径清单与方案反噬</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-14\">十四 · 从论文的扩展性结论反推 kernel 约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-15\">十五 · 数据类型谱系：FP16/BF16/FP8/NVFP4 在 rollout 中的分工</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-16\">十六 · 累加精度与误差传播：为什么分数排序比绝对误差更关键</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-17\">十七 · Blackwell 特性：tcgen05、TMEM、2-SM MMA 与第五代 Tensor Core</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-18\">十八 · 精度选择如何改变 rollout 的吞吐与 SLO</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-19\">十九 · 显存账本的三个账户：权重、激活、KV</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-20\">二十 · 分页与压缩：把 KV 从连续块变成可调度资源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-21\">二十一 · 前缀共享与复用：奖励评估段的重复计算是吞吐黑洞</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-22\">二十二 · 卸载与带宽瓶颈：HBM3e 容量之外的真正约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-23\">二十三 · 可复算的显存预算：一个 70B 档位的完整账本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-24\">二十四 · 长尾与批完成率：显存账本的动态失败模式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-25\">二十五 · 长尾批次的显存账本与失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-26\">二十六 · 连续批处理：把长尾从“整批墙钟”里剥出来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-27\">二十七 · Chunked prefill：把预填充切碎，填进解码的空隙</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-28\">二十八 · 优先级与抢占：让“新鲜度”成为一等调度维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-29\">二十九 · 分离式预填/解码：两种截然不同的负载不该挤在一个池子里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-30\">三十 · 时延与吞吐的取舍面，以及尾延迟怎么压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-31\">三十一 · 长尾样本与奖励评估耦合下的批调度边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-32\">三十二 · 切分维度与RLHF三段流水线的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-33\">三十三 · NVLink 5与NVSwitch：域内带宽的可用边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-34\">三十四 · All-Reduce与All-to-All的代价结构差异</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-35\">三十五 · NIXL传输：KV与权重的跨节点搬运</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-36\">三十六 · 通信何时成为瓶颈：三个可观测判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-37\">三十七 · 拓扑决策与容量规划的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-38\">三十八 · 并行切分在 rollout 流水线上的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-39\">三十九 · 精度塌陷：低精度采样在长尾上的静默失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-40\">四十 · OOM 与批抖动：批大小与长尾的耦合震荡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-41\">四十一 · 尾延迟：生成与评估两段的耦合瓶颈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-42\">四十二 · 静默降级：过滤阈值与权重同步点的隐性代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-43\">四十三 · 回滚与容量判断：把失败模式接进 SLO</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-44\">四十四 · 长尾耦合下的静默降级：从批完成率到回滚闸门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-45\">四十五 · 论文口径的边界：哪些量可换算，哪些不可换算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-46\">四十六 · 硬件档位与 batch 口径：论文没给的，必须自己钉住</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-47\">四十七 · 指标口径：五个指标不能混成一句“更快”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-48\">四十八 · 数字怎么读：三类不可比的提升</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-49\">四十九 · 失败模式的口径归因：论文缺的定量部分怎么补</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-50\">五十 · 口径决定结论：这套扩展性结论在什么条件下失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-51\">五十一 · 迁移的第一道坎：奖励评估的变长输入与前缀复用假设</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-52\">五十二 · 过滤阈值的迁移代价：有效样本产出率与吞吐的再平衡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-53\">五十三 · 长尾分布跨领域漂移：尾部延迟监控不能照搬</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-54\">五十四 · 规模上限：收益递减曲线在rollout侧的映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-55\">五十五 · 低精度采样与异步流水线：迁移时必须单独验证的两处</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-56\">五十六 · 哪里不适用：三条明确的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-57\">五十七 · 迁移不是复制：三条线各自的失效条件与算力换算缺口</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:584px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 584.1 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">策略模型接收提示词批次，按批量调度生成多条候选回复，生成长度分布存在长…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">生成结果送入奖励模型或验证器进行打分，变长输入需要前缀共享与KV复用以…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按打分结果与过滤阈值筛选偏好对，低质量或高噪声样本被剔除。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">筛选后的偏好数据用于后续策略更新，形成异步流水线中的权重同步点。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">长尾样本在生成与评估两段都拖慢批完成时间，需要监控尾部延迟与吞吐。</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">整体rollout与训练解耦，批量生成调度决定单位时间内的有效样本产出。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-1\">一 · 一个夜间在线服务的现场</h3>\n<p>设想一个面向开发者的代码补全服务：白天流量平稳，凌晨两点到四点之间，一批来自自动化评测平台的请求涌入，每条提示词要求生成 4 条候选回复用于后续偏好比较。调度器按批大小 64 把提示词打包，策略模型开始批量生成。问题在二十分钟后暴露：批完成率从 92% 掉到 61%，P99 尾部延迟翻了三倍，而 GPU 的 SM 占用率并没有下降——算力在忙，但有效样本产出在塌陷。根因不在生成本身，而在生成之后：4 条候选里总有一两条长度远超分布中位数，这些超长样本把整批的完成时间钉死在最慢的那条上；紧接着奖励模型要对每条候选打分，变长输入使得前缀无法在批内共享，KV 被反复重算，显存带宽成为第二道墙。运维看到的是延迟，工程上真正发生的是批量生成与奖励评估这两段被长尾样本耦合在一起，任何一段的尾部都会传染给另一段。</p>\n<p>这就是这篇论文出场的问题现场。它问的不是“RLHF 能不能训得更好”，而是“RLHF 的扩展性是否像预训练那样可预测”。在推理侧，这个问题被翻译成一个非常具体的工程追问：当你把数据量、模型规模、方法设计分别往上推一格时，rollout 引擎的单位算力有效样本产出会怎么变？在论文之前，主流推理栈对这个问题的默认回答是“加批量、加算力”，而这正是夜间那场塌陷的来源。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-2\">二 · 论文之前的主流做法：三段串行、批量为王</h3>\n<p>论文之前，RLHF 的 rollout 推理栈基本是三段串行的结构：策略模型批量生成候选、奖励模型或验证器逐条打分、按阈值过滤出偏好对。三段之间以批为同步点，一批生成完才进入打分，打分完才进入过滤。这套做法的隐含假设是：吞吐由批大小决定，批越大，单位时间产出的候选越多，单位算力的偏好数据成本越低。于是调度器的调参旋钮几乎只有一个——批大小与并发度。</p>\n<p>这个假设在短回复、长度分布集中的任务上成立。一旦生成长度呈长尾分布，它就失效。设批内有 $n$ 条候选，第 $i$ 条的生成长度为 $l_i$，批的完成时间由 $\\max_i l_i$ 决定，而有效工作量是 $\\sum_i l_i$。批的“面积效率”可以写成：</p>\n<div class=\"formula\">$$\\eta_{\\text{batch}}=\\frac{\\sum_{i=1}^{n} l_i}{n\\cdot \\max_{i} l_i}$$</div>\n<p>当长度分布方差小，$\\eta_{\\text{batch}}$ 接近 1；当少数样本长度是主体的数倍，$\\eta_{\\text{batch}}$ 迅速跌向 $1/k$（$k$ 为尾部倍数）。批越大，抽到极端长尾样本的概率越高，$\\eta_{\\text{batch}}$ 越差——这与“批越大吞吐越高”的直觉正好相反。夜间服务里批完成率从 92% 掉到 61%，对应的就是 $\\eta_{\\text{batch}}$ 的塌陷，而不是算力不足。</p>\n<p>代价体现在三个维度上。延迟侧，尾部长尾样本决定 P99，批内其他已完成序列的 KV 只能占着显存空等，形成显存驻留浪费；吞吐侧，单位时间有效偏好对的数量被最慢样本拖低；显存与带宽侧，奖励评估段的变长输入若不做前缀共享，同一提示词的 4 条候选会各自重算一遍提示词前缀的 KV，重复计算量正比于候选数。三段串行还把这种浪费放大：生成段的尾部尚未消化，打分段已经因为批同步而空转。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-3\">三 · 奖励评估段的耦合代价</h3>\n<p>第二段的问题独立于生成段，但被同一批同步点绑死。奖励模型或验证器接收的是变长输入：提示词加候选回复。若按“一条候选一次前向”的朴素做法，提示词前缀在 4 条候选上被重复编码 4 次。前缀长度为 $p$、候选长度为 $l$，朴素做法的注意力计算量近似正比于 $\\sum_{j=1}^{4}(p+l_j)^2$，而前缀共享后近似正比于 $p^2+\\sum_j l_j^2+2p\\sum_j l_j$ 的可复用部分。候选数越多、前缀越长，重复计算的占比越高。</p>\n<p>论文明确指出，奖励评估阶段需要前缀共享与 KV 复用来避免重复计算，否则吞吐显著下降。这句话在工程上等价于：奖励模型的批调度不能沿用生成段的“按请求打包”，而必须按前缀分组，把同一提示词的候选聚成一个前缀共享组，KV 在组内复用。这一步在论文之前通常被忽略，因为奖励模型被当作一个“打分黑盒”挂在流水线末端，它的批构造逻辑往往直接复用生成段的调度器。</p>\n<p>显存代价随之而来：前缀 KV 复用要求组内候选的 KV 在打分期间同时驻留，组越大，驻留峰值越高。在长前缀场景（例如带长系统提示或检索上下文的请求）下，前缀 KV 本身就占据可观显存，复用带来的显存压力与它节省的带宽之间需要权衡。论文没有给出量化方案，但把“前缀共享与 KV 复用”列为奖励评估段的核心机制，等于把这一权衡推到了设计台面上。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-4\">四 · 过滤阈值：被当成后处理，其实是吞吐旋钮</h3>\n<p>第三段是偏好数据过滤。论文之前的常见做法是把过滤当作离线后处理：先全量生成、全量打分，再按阈值筛。这个顺序在算力充裕时无害，在算力受限时是纯粹的浪费——低分或高噪声样本在被剔除之前，已经完整地消耗了生成与打分的算力。</p>\n<p>设过滤阈值为 $\\tau$，候选得分分布为 $s$，通过率为 $q(\\tau)=\\Pr[s\\ge\\tau]$。单位算力产出的有效偏好对数量近似正比于 $q(\\tau)$，而单位算力消耗的生成与打分成本正比于 1（全量）。于是有效产出率与总算力之比随 $\\tau$ 上升而单调下降，但偏好对的质量随 $\\tau$ 上升而上升。论文的核心判断之一正在这里：方法层面的改进（偏好数据构造与过滤策略）在同等算力下比单纯堆叠数据与模型规模更稳定。翻译成推理语言：过滤阈值不是质量与吞吐的二选一，而是需要与批调度联动的在线决策——早筛、分级筛、按批动态调阈值，都能把被剔除样本的算力成本压到最低。</p>\n<p>代价是明确的：阈值过高会降低单位算力下的吞吐，因为大量候选在打分后即被丢弃；阈值过低则让低质样本进入异步流水线，污染后续策略更新。论文没有给出具体阈值，但它把过滤从“后处理”提升为“扩展性三要素之一”，意味着调度器必须把过滤通过率作为一等指标纳入批构造，而不是等到流水线末端才看。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-5\">五 · 异步流水线与权重同步点</h3>\n<p>三段之外还有一层：筛选后的偏好数据进入异步流水线，等待权重同步。权重同步点决定样本新鲜度，进而决定 off-policy 程度。论文之前的推理栈通常把 rollout 与训练解耦成两个独立服务，同步点按固定周期触发。这个设计的代价是双重的：同步太频繁，rollout 引擎在同步窗口内空转，吞吐出现周期性凹陷；同步太稀疏，样本由旧策略生成，off-policy 程度上升，策略更新的有效性下降。</p>\n<p>论文的扩展性结论对这一点有直接含义：既然数据与模型规模的边际收益递减，那么“多生成一些旧策略样本”并不能线性换取对齐质量，样本新鲜度的价值相对上升。工程判断是：权重同步点的周期应当由有效样本产出率与 off-policy 容忍度共同决定，而不是由固定时间窗决定。监控上，尾部延迟、批完成率与有效样本产出率三个指标必须同时看——只看吞吐会掩盖长尾，只看延迟会掩盖过滤通过率的塌陷。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-6\">六 · 为什么非改不可：扩展性结论对栈设计的反向约束</h3>\n<p>把上述痛点放回论文的问题框架，结论很清楚：RLHF 的扩展性在数据、模型与方法三个维度上均存在收益递减，方法层面的改进在同等算力下更稳定。这条结论对推理栈构成反向约束——如果继续沿用“加批量、加算力”的旧方案，你买到的是递减的边际收益，同时继承长尾耦合、前缀重算、过滤浪费与同步空转四份固定开销。夜间服务那场塌陷不是偶发，而是旧方案在长尾分布下的必然表现。</p>\n<p>对 Blackwell 部署而言，这意味着容量规划的起点应当从“峰值算力档位”转向“尾部延迟与批完成率的联合分布”。批调度的收益可能高于单纯提升算力档位：更细的批切分、按前缀分组的奖励评估批、在线分级过滤，都是在不增加算力的情况下改善 $\\eta_{\\text{batch}}$ 与有效产出率的手段。论文没有给出硬件档位与并行拓扑，因此这些手段在 B200/B300/GB200 NVL72 上的具体换算需要另行评估；但它把“方法层面的调度与过滤”放在了扩展性结论的中心位置，这本身就是对旧方案最直接的否定。</p>\n<p>具体到机制层面，一个可落地的判断是：把批完成时间从 $\\max_i l_i$ 解耦出来，用“完成即出批”替代“整批同步”，让已完成序列的 KV 立即释放并进入奖励评估的前缀共享组，同时把过滤阈值做成按批通过率反馈的动态量。这三步都不依赖新的算力档位，只依赖调度器对长尾分布的感知——而这正是论文之前的主流推理栈所缺的那一环。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-7\">七 · 批同步屏障：旧 rollout 栈在长尾分布下的结构性失效</h3>\n<p>在线服务的真实形态是：提示词批次进入策略模型，按固定批大小生成多条候选回复，整批生成完毕后统一送入奖励模型打分，再按阈值过滤偏好对。这套流程的致命处在于它把生成与评估串成一道<strong>批同步屏障</strong>——批内最慢的那条样本决定整批的完成时刻。生成长度呈长尾分布，少数超长样本把批完成时间从均值拉到尾部，而奖励评估阶段又因变长输入被迫逐条重算前缀，重复计算直接吃掉吞吐。旧方案的调度逻辑是「凑满一批再走」，批越大单位时间吞吐越高，但尾部延迟风险同步放大，形成吞吐与 SLO 的对冲。</p>\n<p>把代价写成式子更清楚。设批内第 <em>i</em> 条样本生成长度为 <em>L<sub>i</sub></em>，批完成时间由 <em>L<sub>max</sub></em> 决定，而有效吞吐取决于均值：</p>\n<div class=\"formula\">$$T_{\\text{batch}}=\\max_i L_i,\\qquad \\eta=\\frac{B\\cdot \\mathbb{E}[L]}{T_{\\text{batch}}}\\approx\\frac{B\\cdot\\mathbb{E}[L]}{\\max_i L_i}$$</div>\n<p>长尾越重，<em>η</em> 越低。若奖励评估不复用前缀 KV，评估段代价近似正比于 <em>ΣL<sub>i</sub></em> 的二次项（自注意力对变长序列），显存侧则要为整批最长序列预留 KV 空间，短样本的 KV 被浪费，长样本又逼近上限。工程上的直接后果是：批大小不敢开大、显存利用率被最长样本钉死、尾部延迟监控缺失时批完成率悄悄下滑。</p>\n<table class=\"mini\"><thead><tr><th>环节</th><th>旧方案代价</th><th>失效条件</th></tr></thead><tbody><tr><td>批量生成</td><td>批完成时间由 <em>L<sub>max</sub></em> 决定，吞吐随长尾衰减</td><td>长度方差大、超长样本占比升高</td></tr><tr><td>奖励评估</td><td>变长输入逐条重算，前缀 KV 不复用</td><td>候选回复共享前缀比例低</td></tr><tr><td>偏好过滤</td><td>阈值抬高则有效样本产出率下降</td><td>打分噪声大、阈值逼近分布尾部</td></tr></tbody></table>\n<p>论文的扩展性结论正落在这条边界上：数据与模型规模的边际收益递减，意味着继续放大批或堆模型换不来线性吞吐，而方法层面的过滤与调度改进在同等算力下更稳定。对 Blackwell 部署的直接判断是，rollout 引擎的容量规划不能只按峰值算力折算，必须把尾部延迟与批完成率纳入监控，并把前缀共享与 KV 复用前移到奖励评估段——否则批同步屏障会把 NVFP4 采样与 tcgen05 带来的算力增益吞掉，SLO 达成率由最长那条样本单方面决定。</p>\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-8\">八 · 先量清楚请求，再谈调度</h3>\n<p>RLHF rollout 的负载不是一个数，而是一组分布：提示词长度分布、候选回复生成长度分布、每提示的候选条数、并发到达的突发度、以及奖励评估侧的输入长度分布。论文把扩展性拆成数据、模型、方法三条线，但落到引擎上，这四条分布决定了批调度的可行域。工程上必须先固定测量口径，否则“吞吐提升了”这类结论无法复核。建议的口径是：以提示词 token 数为横轴统计 P50/P90/P99，以生成长度为纵轴统计每批的完成时间分位，并单独记录“批内最长样本”与“批内中位样本”的完成时间差。这个差值就是长尾税。</p>\n<p>论文明确指出生成长度呈长尾分布，少数超长样本拖慢整批完成时间。这句话的工程含义是：连续批处理（continuous batching）中，一个 batch 的释放时刻由最慢序列决定，而不是平均序列。设批内有 $n$ 条序列，第 $i$ 条的生成长度为 $L_i$，解码步耗时近似正比于活跃序列数与 KV 读取量，则批完成时间可写成</p>\n<div class=\"formula\">$$T_{\\text{batch}} \\approx \\sum_{t=1}^{\\max_i L_i} \\tau\\bigl(a(t),\\, \\text{KV}(t)\\bigr),\\quad a(t)=\\#\\{i: L_i \\ge t\\}$$</div>\n<p>其中 $a(t)$ 是第 $t$ 步仍活跃的序列数。长尾样本让 $\\max_i L_i$ 远大于中位数，而 $a(t)$ 在尾部迅速塌缩到个位数——此时 GPU 的 MMA 单元利用率极低，但 KV cache 仍被这些序列占着。这就是“批越大吞吐越高但尾部延迟风险越大”的机理：增大批提升的是 $a(t)$ 的均值段利用率，代价是把 $\\max_i L_i$ 的期望也推高。</p>\n<p>具体例子：一个提示批次含 64 条请求，中位生成长度落在数百 token 量级，但存在个别样本生成到数千 token。若按静态批提交，整批必须等最长者结束才能进入奖励评估，中间数十条已完成序列的 KV 无法释放，显存占用被尾部样本钉住。可核查的测量方式是记录每条序列的“完成时刻减提交时刻”并画生存曲线，同时记录批内已完成但未释放的 KV 块数——后者直接对应显存浪费。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-9\">九 · 并发与 SLO：两个约束互相挤压</h3>\n<p>SLO 在 rollout 场景里通常不是单一指标，而是三元组：首 token 延迟上限、每请求端到端延迟上限、以及单位时间有效偏好对产出下限。论文的方法论结论——方法层面的改进在同等算力下比堆数据堆模型更稳定——在容量规划上翻译为：与其把并发拉满换取峰值吞吐，不如把过滤策略与调度策略调好，让单位算力的有效样本率上升。因为过滤阈值直接影响有效样本产出率，阈值过高会降低单位算力下的吞吐，这是一条与并发正交的杠杆。</p>\n<p>并发与 SLO 的挤压关系可以用一个简单的排队近似刻画。设到达率为 $\\lambda$、单请求平均服务时间为 $\\mathbb{E}[S]$、服务时间变异系数为 $C_S$，则在多服务器近似下有</p>\n<div class=\"formula\">$$\\mathbb{E}[W_q]\\approx \\frac{C_S^2}{2}\\cdot\\frac{\\rho}{1-\\rho}\\cdot\\mathbb{E}[S],\\quad \\rho=\\lambda\\,\\mathbb{E}[S]/m$$</div>\n<p>长尾分布意味着 $C_S$ 显著大于 1，同样的 $\\rho$ 下排队延迟被放大。这解释了为什么在长尾负载下“把并发再提一点”很快撞上 P99 延迟墙：$\\rho$ 接近 1 时 $1/(1-\\rho)$ 发散，而 $C_S^2$ 又乘在前面。工程判断是：对长尾 rollout，应按 P99 而非均值做容量规划，并把超长样本从主批次中剥离。</p>\n<p>具体机制上，可行的做法是长度分桶加溢出队列：预估长度落在短桶的请求走高频小批，预估落在长桶的走低频大批并配更长 SLO；无法预估的走观察队列，生成到阈值后强制截断或转异步。代价是分桶本身引入调度开销与桶间负载不均，短桶可能空转而长桶排队。可核查口径：分别统计各桶的批完成率、桶间迁移率、以及被截断样本占有效样本的比例——最后一项直接侵蚀论文所强调的“有效偏好数据量”。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-10\">十 · 批大小如何反向塑造负载</h3>\n<p>批大小不是被动参数，它会反过来改变负载形态。增大批会提高解码阶段的算术强度，但也会拉长单批驻留时间，使后续到达的请求排队更久；同时更大的批意味着奖励评估阶段一次送入更多变长输入，前缀共享的命中率随之变化。论文强调奖励模型或验证器评估变长输入时需要前缀共享与KV复用，否则重复计算显著降低吞吐。批越大，前缀多样性越高，共享前缀的命中率越可能下降——这是一个被忽略的反向作用。</p>\n<p>设一批内有 $B$ 条候选，其提示前缀去重后长度为 $U$，总前缀长度为 $S$，则前缀复用带来的计算节省比例近似为 $1-U/S$。当 $B$ 增大而提示来源分散时，$U$ 趋近 $S$，节省比例趋零；反之若同一提示生成多条候选（论文流程中策略模型对每个提示批量生成多条回复），$U$ 固定而 $S$ 随候选数线性增长，节省比例趋近 $1-1/k$（$k$ 为每提示候选数）。这给出一个可操作的判断：批的构成比批的大小更重要，按提示聚合候选比按到达顺序拼批更能吃到 KV 复用收益。</p>\n<p>代价方面：按提示聚合会降低调度灵活性，同一提示的候选必须等齐才能成批，增加了提示级尾延迟；而按到达顺序拼批虽灵活，却在奖励评估段付出重复前缀计算。可核查测量口径是分别记录生成段与评估段的 KV 命中块数与总块数之比，以及两段的 token 吞吐。若评估段命中率低而生成段高，说明批构成偏向到达顺序，应考虑改为提示聚合。Blackwell 上 TMEM 与 2-SM MMA 的收益依赖批内矩阵形状稳定，批构成抖动会削弱这些算子优势，这一点在容量规划时应与命中率一并纳入。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-11\">十一 · 长尾的两段耦合：生成拖一次，评估再拖一次</h3>\n<p>论文的失败模式描述得很具体：长尾样本在生成与评估两段都拖慢批完成时间。这不是两次独立的长尾，而是耦合的——生成段产出的超长回复，恰好是评估段最长的输入，且其 KV 在生成段已占用大量显存，评估段还要再为它做一次前向。若评估与生成共享同一批 GPU，两段的长尾会叠加；若分离部署，长尾则从生成段转移到评估段的队列。</p>\n<p>耦合的量化方式是定义“双段尾延迟”：对每条请求记录 $T_{\\text{gen}}$ 与 $T_{\\text{eval}}$，统计 $T_{\\text{gen}}+T_{\\text{eval}}$ 的 P99 与 P50 之比。论文未给出具体数字，因此这个比值只能作为自建监控指标，不能引用为论文结论。工程上更实用的是“批完成率”：单位时间内完整走完生成加评估的批数除以提交批数。批完成率下降而单段吞吐不变，基本可判定为长尾耦合而非算力不足。</p>\n<p>具体机制上，缓解手段包括：对生成段设长度上限并在达到上限时提前释放 KV、把评估段改为流式打分（生成一段评一段，而非等整条回复完成）、以及为超长样本单开低速通道避免污染主批。代价是流式打分需要奖励模型支持增量输入，且前缀 KV 要在两段之间保持有效，跨段 KV 交接的显存开销与同步开销需单独计量。可核查口径：跨段 KV 交接的块数、交接等待时间占端到端延迟的比例、以及低速通道样本的有效样本产出率——若低速通道产出率过低，说明截断阈值设得太紧，反而损伤论文所看重的数据质量。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-12\">十二 · 异步流水线与权重同步：负载形态的第三维</h3>\n<p>论文提到筛选后的偏好数据进入异步流水线等待权重同步，权重同步点决定样本新鲜度，进而影响 off-policy 程度。这条对负载形态的影响常被低估：同步点是一个周期性的事件，它会把连续的 rollout 负载切成一段段，同步窗口内生成暂停或降速，窗口结束后出现到达突发。负载因此不是平稳泊松，而是带周期性突发的形态，前面排队公式里的 $\\lambda$ 应替换为时变到达率。</p>\n<p>设同步周期为 $T_s$，同步窗口长度为 $W$，窗口内有效服务能力降为 $\\alpha m$（$\\alpha&lt;1$），则周期内的等效利用率上升为 $\\rho'=\\lambda\\mathbb{E}[S]/(\\alpha m)$ 在窗口段、$\\rho$ 在非窗口段。若 $\\rho'$ 接近 1，窗口段排队延迟急剧上升，且窗口结束后的突发会进一步推高瞬时 $\\rho$。工程判断是：同步窗口应尽量与长尾样本的处理错开——把超长样本安排在同步窗口内低速推进，把短样本安排在窗口外高频推进，用负载形态去填同步造成的算力空洞。</p>\n<p>可核查测量口径：记录同步事件的时刻与持续时长、窗口内与窗口外的批完成率之比、以及窗口结束后突发的队列深度峰值。另一个关键指标是样本新鲜度，即样本生成时刻到被用于策略更新的时间差，其分布直接对应 off-policy 程度。论文的方法论结论提示过滤策略比堆规模更稳定，而过滤发生在同步点之前，因此同步周期过长会让过滤后的数据变旧，抵消过滤带来的质量收益。代价上，缩短同步周期提升新鲜度但增加同步开销与突发频率，这是一个需要按任务容忍度调的参数，而非固定值。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-13\">十三 · 测量口径清单与方案反噬</h3>\n<p>把上述讨论收敛成一份可复核的清单，用于判断负载是否被方案反噬。第一层是输入侧：提示长度分位、每提示候选数、到达率的时变性。第二层是生成侧：生成长度分位、批内最长与中位完成时间差、已完成未释放 KV 块数。第三层是评估侧：变长输入的前缀去重率、KV 命中块数比、评估段 token 吞吐。第四层是端到端：双段尾延迟比、批完成率、有效样本产出率、样本新鲜度分布。第五层是资源：显存峰值中长尾样本占比、同步窗口内算力利用率。</p>\n<p>方案反噬的典型形态有三种。其一，为提吞吐而增大批，导致前缀命中率下降与尾延迟上升，净吞吐反而下降——判据是评估段命中率与批完成率同时走低。其二，为降尾延迟而强制截断，导致有效样本产出率下降，单位算力有效数据量减少——判据是截断比例上升而过滤后样本质量指标未改善。其三，为提新鲜度而缩短同步周期，导致突发频率上升、排队延迟 P99 恶化——判据是窗口外突发队列深度峰值随周期缩短而单调上升。</p>\n<p>对 Blackwell 部署而言，材料未给出硬件档位与并行拓扑，因此上述指标只能作为相对口径使用，不能直接换算为绝对吞吐。可做的工程判断是：在 NVFP4/FP8 路径下，批内形状稳定性对 tcgen05 与 2-SM MMA 的利用率影响显著，而长尾与批构成抖动正是形状不稳定的来源；因此长尾治理不只是延迟问题，也是低精度算子能否吃满的问题。采样稳定性在低精度下需单独验证，这一点论文未讨论，不能假定其结论可直接迁移。最终落点是一个具体机制：把“批内最长样本完成时刻”作为一级调度信号，而非事后统计——当它超过阈值时触发批拆分与 KV 提前释放，用调度动作直接切断长尾向评估段的传导。</p>\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-14\">十四 · 从论文的扩展性结论反推 kernel 约束</h3>\n<p>论文把 RLHF 的可扩展性拆成数据、模型、方法三条线，结论是三者都存在收益递减，而方法层面的改进在同等算力下更稳定。这条结论落到推理侧，等价于一句话：<strong>单位算力产出的有效偏好对数量，比单步 kernel 的峰值算力更能决定扩展曲线</strong>。rollout 阶段由策略模型批量生成候选回复，长度呈长尾；奖励模型或验证器随后对变长输入打分。两段之间的数据流不是均匀张量，而是长度参差的序列集合，这直接决定了核心 kernel 的选型：生成段是自回归解码，算力密度低、访存密集；评估段是变长前向，需要前缀共享与 KV 复用。论文强调方法层面（偏好数据构造与过滤）比堆数据堆模型更稳，工程含义是过滤阈值改变了有效样本产出率，而产出率的分母正是这两段 kernel 消耗的算力与时间。因此本节不讨论“用哪个精度更快”这种孤立问题，而是讨论在长尾批与变长评估的耦合下，精度与累加策略如何改变尾延迟与有效吞吐。</p>\n<p>把论文的目标函数放在这里作为参照，它决定了推理侧要评估什么量：</p>\n<div class=\"formula\">$$\\mathcal{L}_{\\text{RLHF}}(\\theta)=\\mathbb{E}_{x\\sim\\mathcal{D},\\,y\\sim\\pi_\\theta(\\cdot|x)}\\left[r_\\phi(x,y)\\right]-\\beta\\,\\mathrm{KL}\\left(\\pi_\\theta(\\cdot|x)\\,\\|\\,\\pi_{\\text{ref}}(\\cdot|x)\\right)$$</div>\n<p>逐项看：第一项要求对策略采样出的 $y$ 计算奖励 $r_\\phi$，推理上对应“生成 + 评估”两段前向；第二项需要参考模型 $\\pi_{\\text{ref}}$ 的对数概率，推理上是第三条前向流。三项叠加意味着每个候选回复至少要过三次模型计算（策略生成、奖励打分、参考对数概率），其中参考模型的前向可以与奖励模型共享前缀 KV，但前提是两者的分词与位置编码一致。这就是为什么前缀共享不是优化技巧而是容量规划的前提：不共享，单位样本的算力开销按前向次数线性放大；共享，则变长输入的重复计算被压到前缀一次。论文没有给出量化方案，因此这里只能定性判断：任何降低单次前向代价的精度选择，都必须先保证这三条流的数值一致性，否则 KL 项的估计偏差会直接污染过滤阈值的判定。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-15\">十五 · 数据类型谱系：FP16/BF16/FP8/NVFP4 在 rollout 中的分工</h3>\n<p>Blackwell 世代的推理栈通常按“谁对数值最敏感”来分配精度，而不是全模型统一一种格式。策略模型的<strong>权重</strong>可以用 FP8 或 NVFP4 存储以压缩显存与带宽，因为解码阶段的瓶颈是权重读取而非算力；<strong>激活</strong>在自回归解码中逐 token 产生，KV cache 的精度选择直接影响长尾样本的显存占用；<strong>累加</strong>则几乎总是留在 FP32，这是误差控制的底线。BF16 与 FP16 的取舍在于动态范围：BF16 指数位与 FP32 相同，长尾生成中偶发的激活尖峰不易溢出，适合策略模型与参考模型；FP16 尾数更多，在奖励模型的打分头上能保留更细的分数分辨率，但需要缩放因子防止溢出。FP8 分 E4M3 与 E5M2 两族，前者尾数多适合权重与激活，后者动态范围大适合梯度类场景——推理侧主要用 E4M3。NVFP4 是 Blackwell 的 4 位块浮点格式，配合块级缩放因子，把权重压到每元素 4 位，代价是量化误差随块内动态范围增大而上升。</p>\n<table class=\"mini\"><thead><tr><th>数据对象</th><th>典型格式</th><th>推理侧代价</th><th>与论文流程的耦合点</th></tr></thead><tbody><tr><td>策略权重</td><td>FP8 E4M3 / NVFP4</td><td>显存与权重带宽下降，解码吞吐上升</td><td>批量生成段的批大小上限</td></tr><tr><td>KV cache</td><td>FP8 / BF16</td><td>长尾样本显存占用，决定并发度</td><td>前缀共享与 KV 复用的粒度</td></tr><tr><td>奖励模型权重</td><td>FP8 / BF16</td><td>评估段前向延迟</td><td>变长输入打分的批完成时间</td></tr><tr><td>累加器</td><td>FP32</td><td>Tensor Core 内部吞吐折损</td><td>分数分辨率与过滤阈值判定</td></tr></tbody></table>\n<p>具体例子：一条超长候选回复在解码时逐 token 写入 KV cache，若 KV 用 FP8 存储，同样显存可容纳更多并发序列，但分数头若也用 FP8 累加，奖励分数的排序可能在阈值附近翻转，导致本应保留的偏好对被误剔。论文的方法层面结论恰恰依赖过滤策略的稳定性，因此奖励模型的<strong>输出层与累加</strong>应保留 BF16/FP32，只把其主干权重降到 FP8。这是“精度按敏感度分层”的直接工程判断，而不是全局统一量化。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-16\">十六 · 累加精度与误差传播：为什么分数排序比绝对误差更关键</h3>\n<p>低精度矩阵乘的误差主要来自两方面：输入量化的舍入误差，以及累加过程中的截断。设一次点积长度为 $K$，输入被量化到 $b$ 位，则单次乘加的相对误差量级约为 $2^{-b}$，而 $K$ 项累加若在低精度下进行，误差按 $\\sqrt{K}$ 量级随机游走（独立舍入假设下），最坏情况按 $K$ 线性增长。Blackwell 的 Tensor Core 在 FP8 与 NVFP4 模式下提供 FP32 累加，正是为了把 $K$ 项求和的截断误差压到可忽略，代价是累加器位宽带来的寄存器压力与吞吐折损。用公式表达奖励分数的误差上界：</p>\n<div class=\"formula\">$$\\left|\\hat{r}-r\\right|\\lesssim \\underbrace{\\epsilon_q\\sum_{k}\\left|w_k x_k\\right|}_{\\text{量化误差}}+\\underbrace{\\epsilon_a\\sum_{k}\\left|w_k x_k\\right|}_{\\text{累加截断}}$$</div>\n<p>其中 $\\epsilon_q$ 由输入格式的尾数位决定（FP8 E4M3 约 $2^{-4}$ 量级，NVFP4 更粗），$\\epsilon_a$ 由累加器精度决定（FP32 下可忽略）。逐项解释：第一项随权重与激活的绝对值之和放大，长尾样本中激活尖峰会让这一项显著变大；第二项在 FP32 累加下基本消失，但如果为了省寄存器把累加降到 FP16，$\\epsilon_a$ 会重新进入误差预算。工程含义是：<strong>把权重降到 NVFP4 时，必须保留 FP32 累加，并且对激活做块级缩放</strong>，否则奖励分数的绝对误差会随序列长度增长，而过滤阈值是全局固定的，误差增长直接转化为误判率上升。</p>\n<p>更关键的是排序而非绝对值。RLHF 的偏好对构造依赖同一提示下多条候选的相对分数，若两条候选的分数差小于误差量级，排序就不可靠。设两条候选分数差为 $\\Delta r$，误差上界为 $\\epsilon$，则可靠排序要求 $\\Delta r&gt;\\epsilon$。长尾样本的 $\\epsilon$ 更大，因此同一批内超长样本的偏好对质量更差。这与论文“长尾样本在生成与评估两段都拖慢批完成时间”的观察形成互补：长尾不仅拖时间，还拖数值可靠性。工程上应对的办法是对长尾样本单独用更高精度重算分数，或提高其过滤阈值，用少量算力换取偏好对质量。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-17\">十七 · Blackwell 特性：tcgen05、TMEM、2-SM MMA 与第五代 Tensor Core</h3>\n<p>Blackwell 的第五代 Tensor Core 引入了 tcgen05 指令族，其核心变化是把矩阵乘的累加器从寄存器文件搬到 <strong>Tensor Memory（TMEM）</strong>。TMEM 是每个 SM 私有的片上存储，专门承载 MMA 的累加结果，使得大尺寸 MMA 不再受寄存器数量限制，同时把累加器与通用寄存器的压力解耦。对推理的直接意义是：变长评估段中，奖励模型的前向可以按更大的 tile 切分而不必担心寄存器溢出，累加精度得以稳定保持在 FP32。2-SM MMA 则允许两个 SM 协同完成一次 MMA，把单个 MMA 的规模翻倍，适合权重驻留、激活流式的评估场景；代价是跨 SM 的同步开销，只有在 tile 足够大、计算密度足够高时才划算。</p>\n<p>用伪代码思路描述一次带 TMEM 累加的评估 kernel 的数据流：</p>\n<div class=\"formula\">$$\\text{for } t \\text{ in tiles: } \\;\\; \\text{load } W_t\\rightarrow\\text{SMEM},\\; X_t\\rightarrow\\text{reg};\\; \\text{tcgen05.mma}(W_t,X_t)\\rightarrow\\text{TMEM};\\; \\text{epilogue(TMEM)}\\rightarrow\\text{score}$$</div>\n<p>逐项解释：权重 tile 进共享内存，激活 tile 留在寄存器，MMA 的累加结果写入 TMEM 而非寄存器堆；epilogue 阶段从 TMEM 读出累加值做缩放、偏置与激活，再写出分数。这条流水线的代价在于 TMEM 容量有限，tile 尺寸与并发 warp 数需要平衡；若 tile 过大导致 TMEM 占满，后续 MMA 只能等待 epilogue 排空，形成流水线气泡。对长尾批而言，气泡会被最短与最长序列的完成时间差放大——批内序列长度参差，短序列先完成、长序列占着 TMEM 与 SM 不放，尾延迟上升。工程判断是：评估段应按长度分桶，把长尾样本集中到独立批次，避免它们与短样本共享同一 MMA 流水线。</p>\n<p>第五代 Tensor Core 对 FP8 与 NVFP4 的原生支持是另一条线索。NVFP4 的块级缩放因子在硬件中随 MMA 一起应用，意味着量化误差在乘加内部就被缩放吸收，而不是在软件层逐元素乘缩放因子。这降低了 epilogue 的算力开销，但也意味着缩放因子的选择（块大小、每块指数）直接决定误差分布。块越小，动态范围跟踪越细，误差越小，但元数据开销越大；块越大，压缩率越高，长尾激活尖峰越容易被同一缩放因子压扁。论文没有给出 NVFP4 采样稳定性的讨论，因此部署时必须单独验证：在策略模型采样温度较高时，NVFP4 权重的生成分布是否仍能支撑奖励模型的排序分辨力。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-18\">十八 · 精度选择如何改变 rollout 的吞吐与 SLO</h3>\n<p>把上述机制折算成系统代价，可以看到三条相互牵制的曲线。第一，权重精度下降使权重带宽需求下降，解码段每 token 的显存读取时间缩短，批量生成的吞吐上升；但 KV cache 若同步降精度，长尾样本的显存占用下降、并发度上升，代价是注意力分数的数值噪声增大，长序列上的分数漂移会改变生成分布。第二，评估段用 FP8 主干加 FP32 累加，前向延迟下降，但 epilogue 与分数重算的开销在长尾样本上不可忽略。第三，过滤阈值是全局参数，精度误差使阈值附近的判定不稳定，有效样本产出率下降，抵消了吞吐收益。</p>\n<p>具体例子：一个提示批次生成多条候选，其中少数超长样本决定了整批完成时间。若 KV cache 用 FP8，显存可容纳更多并发，批完成时间由最长样本的解码步数决定而非显存容量决定，此时吞吐提升有限；若把长尾样本单独分桶并用 BF16 KV 重算分数，尾延迟可控但总算力开销上升。工程上应监控三个量：尾部延迟（批完成时间的分位数）、批完成率（单位时间完成的批数）、有效样本产出率（过滤后保留的偏好对除以消耗的算力时间）。论文的方法层面结论提示，优化过滤与调度策略的收益高于单纯提升算力档位，这三项监控正是把该结论落到容量规划的操作面。</p>\n<p>最后落到一个具体机制上：奖励模型的分数头应固定为 BF16 或 FP32 累加，主干权重按 FP8/NVFP4 分层量化，KV cache 精度按序列长度分桶——短样本用低精度换并发，长尾样本用高精度保排序。这一分层不是精度偏好，而是由论文“长尾样本与奖励评估耦合是主要失败模式”直接推出的工程约束：数值误差在长尾上放大，而长尾又决定批完成时间，两者叠加使统一精度策略在尾延迟与偏好对质量之间无法同时满足。</p>\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-19\">十九 · 显存账本的三个账户：权重、激活、KV</h3>\n<p>在 Blackwell 上做 RLHF rollout，显存不是一块整账，而是三个互不相让的账户。权重账户是静态的：策略模型与奖励模型（或验证器）同时驻留，若二者共享主干则只算一份，否则按参数量与精度折算。激活账户是动态的：批量生成时每 token 的中间张量随批大小与序列长度线性增长，tcgen05 的 TMEM 占用与 2-SM MMA 的跨 SM 协作会额外占用片上资源，这部分不落在 HBM 但约束了可并发的 CTA 数量。KV 账户是累积的：每条候选回复的 KV 随生成长度单调增长，长尾样本正是这个账户的爆点。</p>\n<p>账本的基本恒等式是：</p>\n<div class=\"formula\">$$M_{\\text{HBM}} = \\underbrace{N_p \\cdot b_w}_{\\text{权重}} + \\underbrace{B \\cdot s \\cdot h \\cdot d \\cdot b_a}_{\\text{激活}} + \\underbrace{2 \\cdot L \\cdot n_{\\text{kv}} \\cdot d_h \\cdot b_{\\text{kv}} \\cdot \\sum_{i} s_i}_{\\text{KV}} + M_{\\text{workspace}}$$</div>\n<p>其中 $N_p$ 为参数量，$b_w$ 为权重字节数（NVFP4 为 0.5 字节/参数，FP8 为 1，BF16 为 2），$B$ 为批大小，$s$ 为序列长度，$L$ 为层数，$n_{\\text{kv}}$ 为 KV 头数，$d_h$ 为头维，$\\sum_i s_i$ 是批内各序列长度之和。关键在最后一项：它不是 $B \\cdot s_{\\max}$，而是实际长度之和——长尾样本让这个和远大于均值乘批大小，这正是论文强调的“少数超长样本拖慢整批完成时间”在显存侧的投影。</p>\n<p>具体例子：一个 70B 级策略模型以 NVFP4 驻留，权重约 35 GB；同档奖励模型若独立部署再占 35 GB，GB200 NVL72 单 GPU 的 HBM3e 容量虽足以容纳二者，但留给 KV 的空间被压缩到不足一半。此时批大小与最大生成长度必须联合裁剪，否则 KV 账户先于权重账户触顶。代价是吞吐：批大小下降直接压低 token/s，而奖励评估段的变长输入又要求前缀共享，账本必须在两段之间做权衡。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-20\">二十 · 分页与压缩：把 KV 从连续块变成可调度资源</h3>\n<p>连续分配的 KV 缓存有两个浪费：内部碎片（按最大长度预留）与外部碎片（不同请求长度不一）。分页 KV 把缓存切成固定大小的 block，按需映射到物理页，逻辑长度与物理占用解耦。在 Blackwell 上这套机制与 TMEM 的分配粒度需要对齐——tcgen05 的矩阵描述符按 tile 组织，KV block 大小若与 MMA tile 不整除，会引入额外的重排开销。</p>\n<p>压缩有三条正交路径。其一是头维压缩：GQA/MLA 把 $n_{\\text{kv}}$ 从 $n_h$ 降到 1/4 或更低，KV 账本按比例缩小，代价是表达力与采样稳定性需单独验证（材料未给出 NVFP4 采样稳定性的讨论，这条路径在低精度下尤其要谨慎）。其二是量化：KV 以 FP8 存储，$b_{\\text{kv}}$ 从 2 降到 1，账本减半，但注意力分数的数值误差会累积到长序列尾部。其三是 token 级驱逐：对已完成的候选回复，低注意力权重的 token 可被回收，但 RLHF 的奖励评估需要完整回复，驱逐只能发生在生成段之后、评估段之前的窗口。</p>\n<p>系统代价的量化：以 $L=80$、$n_{\\text{kv}}=8$、$d_h=128$、FP8 KV 为例，每 token 的 KV 字节数为 $2 \\times 80 \\times 8 \\times 128 \\times 1 = 163{,}840$ 字节，约 160 KB。一条 8K token 的回复占 1.3 GB；批内 32 条、平均 4K、尾部 16K 时，$\\sum_i s_i$ 约为 160K token，KV 账户约 26 GB。分页把尾部样本的预留从 16K 降到实际用量，节省的正是均值与最大值之差——这部分直接转化为可增加的批大小。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-21\">二十一 · 前缀共享与复用：奖励评估段的重复计算是吞吐黑洞</h3>\n<p>论文的流程里，策略模型生成候选回复后送入奖励模型或验证器打分。若每个候选独立编码提示词前缀，同一提示词的 KV 被重复计算 $k$ 次（$k$ 为候选数）。前缀共享把这部分 KV 只算一次，后续候选通过页表指向同一物理页，只在分叉点之后追加各自的 KV。这是 rollout 引擎最直接的吞吐杠杆：提示词越长、候选越多，收益越大。</p>\n<p>复用的伪代码思路是：</p>\n<div class=\"formula\">$$\\text{prefix\\_pages} = \\text{encode}(x);\\ \\ \\forall j:\\ \\text{kv}_j = \\text{prefix\\_pages} \\oplus \\text{decode}(y_j \\mid \\text{prefix\\_pages})$$</div>\n<p>工程上要注意两点。第一，前缀页在生成段与评估段之间必须保持有效，不能被生成段的驱逐策略回收，否则评估段要重算。第二，奖励模型与策略模型若共享分词与位置编码，前缀页可跨模型复用；若不共享，则只能段内复用。论文材料未给出并行切分方式，因此在张量并行下前缀页的切分需与 KV 头的切分对齐，否则跨卡复用会引入通信。</p>\n<p>代价对比：假设提示词 2K token、每提示 8 条候选、批内 16 个提示。不共享时前缀 KV 计算量为 $16 \\times 8 \\times 2\\text{K} = 256\\text{K}$ token；共享后降为 $16 \\times 2\\text{K} = 32\\text{K}$ token，计算量降为 1/8。在带宽受限的解码阶段，这直接体现为评估段延迟的下降；而在容量侧，共享页只占一份物理内存，KV 账户按提示数而非候选数计费。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-22\">二十二 · 卸载与带宽瓶颈：HBM3e 容量之外的真正约束</h3>\n<p>HBM3e 的容量账好算，带宽账难算。解码阶段每生成一个 token，需要把权重与 KV 全部读一遍，算术强度极低，瓶颈在 HBM 带宽而非算力。设权重字节 $b_w N_p$、KV 字节 $M_{\\text{kv}}$，单 token 的访存量约为二者之和，则解码吞吐的上界为：</p>\n<div class=\"formula\">$$\\text{tokens/s} \\le \\frac{\\text{BW}_{\\text{HBM}}}{b_w N_p + M_{\\text{kv}}(s)}$$</div>\n<p>这个式子说明两件事。其一，批大小增大时 $M_{\\text{kv}}$ 随批线性增长，分母变大，单 token 吞吐下降，但总吞吐（乘批大小）仍上升，直到带宽饱和——这是连续批处理的收益来源。其二，权重精度直接决定分母：NVFP4 把 $b_w$ 压到 0.5，分母的权重项减半，解码吞吐上界近似翻倍，这也是 Blackwell 上低精度推理的核心动机。</p>\n<p>卸载（offload）是容量不足时的兜底：把不活跃的 KV 页或奖励模型权重换出到主机内存，按需换入。代价是 PCIe 带宽远低于 HBM，换入换出会打断解码流水，尾部延迟显著恶化。工程判断是：卸载只应用于低频访问的奖励模型权重或已完成的候选 KV，绝不应用于正在解码的活跃页。GB200 NVL72 的机架级 NVLink 5 让跨 GPU 的 KV 共享比跨主机卸载便宜得多，容量规划应优先考虑机架内分布式 KV 而非主机卸载。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-23\">二十三 · 可复算的显存预算：一个 70B 档位的完整账本</h3>\n<p>下面给出一个可复算的预算模板，读者可按自己的模型档位替换参数。假设：策略模型 70B、NVFP4 权重、80 层、$n_{\\text{kv}}=8$、$d_h=128$、FP8 KV；奖励模型 70B 独立部署、NVFP4；批内 16 个提示、每提示 8 条候选、平均生成长度 4K、尾部 16K；前缀 2K token 共享。</p>\n<table class=\"mini\">\n<thead><tr><th>账户</th><th>计算式</th><th>占用</th></tr></thead>\n<tbody>\n<tr><td>策略权重</td><td>$70\\text{B} \\times 0.5$ B</td><td>35 GB</td></tr>\n<tr><td>奖励权重</td><td>$70\\text{B} \\times 0.5$ B</td><td>35 GB</td></tr>\n<tr><td>前缀 KV（共享）</td><td>$16 \\times 2\\text{K} \\times 160$ KB</td><td>5.1 GB</td></tr>\n<tr><td>候选 KV（生成段）</td><td>$16 \\times 8 \\times 4\\text{K} \\times 160$ KB</td><td>81.9 GB</td></tr>\n<tr><td>尾部增量</td><td>尾部样本超出均值的部分</td><td>按实际长度补</td></tr>\n<tr><td>激活与工作区</td><td>批大小 × 序列 × 隐维 × 字节</td><td>数 GB 量级</td></tr>\n</tbody>\n</table>\n<p>账本读法：权重 70 GB 是硬占用，KV 在生成段峰值接近 90 GB，加上激活与工作区，单卡 HBM3e 容量在 192 GB 档位下已接近饱和。若把奖励模型与策略模型共享主干，权重降到 35 GB，KV 空间翻倍，批大小可提升——这正是“方法层面改进优于堆叠规模”在显存侧的体现：共享与复用是方法，扩容是堆叠。反过来，若坚持独立部署两个 70B 模型，则必须靠分页压缩候选 KV 或降低批内候选数，代价是有效样本产出率下降，直接冲击论文关注的单位算力有效偏好数据量。</p>\n<p>预算的可复算性在于每个账户都有闭式表达，替换 $N_p$、$L$、$n_{\\text{kv}}$、$b_w$、$b_{\\text{kv}}$ 即可重算。工程上应把这张表做成容量规划的输入，而不是事后诊断：批大小、候选数、最大生成长度三个旋钮共同决定 KV 账户，而长尾分布决定尾部增量，三者必须在 SLO 约束下联合求解。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-24\">二十四 · 长尾与批完成率：显存账本的动态失败模式</h3>\n<p>静态账本算的是峰值，动态失败模式出在长尾。批内一条 16K 的样本让整批的 KV 账户按最坏情况预留，而分页只能缓解不能消除——因为该样本在完成前始终占着物理页。批完成率因此成为比平均延迟更敏感的指标：一条长尾样本拖住整批，后续批无法进入，吞吐按批完成率的倒数衰减。</p>\n<p>监控应覆盖三个量：尾部延迟（P99 生成长度对应的完成时间）、批完成率（单位时间完成的批数）、有效样本产出率（过滤后进入偏好数据的样本数除以总算力）。论文材料未给出定量失败模式分析，这三个量需自行补齐。工程判断是：当尾部延迟的增速超过批大小增速时，扩批已无收益，应转向前缀共享与 KV 压缩；当有效样本产出率随过滤阈值上升而下降时，说明方法层面的过滤策略已成为瓶颈，而非算力。</p>\n<p>最后落在一个具体机制上：分页 KV 的页表在批完成时释放物理页，释放顺序应与批调度器的准入顺序一致，否则新批因页碎片无法获得连续 tile，tcgen05 的 MMA 描述符被迫重排，解码流水出现空洞。这个空洞在账本上不可见，却直接吃掉批完成率——它是显存账本与调度策略之间的接缝，也是 Blackwell rollout 引擎调优时最容易被忽略的一处。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-25\">二十五 · 长尾批次的显存账本与失效边界</h3>\n<p>把权重、激活、KV 三本账放在同一张预算表上时，RLHF rollout 的特殊性在于：KV 账本不是按平均长度结算，而是按批内最长样本结算。策略模型批量生成候选回复，生成长度呈长尾分布，少数超长样本拖慢整批完成时间；在这段等待里，短样本的 KV 已经可以释放，长样本却持续占用分页块，奖励模型或验证器随后还要对变长输入做前缀共享与 KV 复用。若引擎按均值预留 KV 块，尾部样本会触发抢占或换出，把一次生成拆成多段重算；若按最坏长度预留，短样本的槽位被白白锁定，吞吐随批大小上升反而下降。可复算的账本应写成：单批 KV 峰值 = 批内最长序列 token 数 × 层数 × KV 头数 × 头维 × 每元素字节 × 并发副本数，再叠加权重常驻与激活峰值；分页块大小决定碎片率，块越大，尾部浪费越多，块越小，页表开销与调度开销越高。</p>\n<p>失效条件集中在三处。其一，过滤阈值过高会降低单位算力下的有效样本产出率，被剔除的候选在打分前已经消耗了完整 KV 与生成算力，等于用显存换来了废样本；阈值过低则偏好对噪声上升，异步流水线中权重同步点带来的 off-policy 程度被放大。其二，前缀共享只在提示词批次高度同源时成立，一旦奖励模型输入由多条候选拼接而成，共享前缀被截断，复用率骤降，重复计算重新成为吞吐瓶颈。其三，长尾样本在生成与评估两段都拖慢批完成时间，尾部延迟与批完成率必须同时监控，否则容量规划会把慢批误判为算力不足。材料未给出具体硬件档位与并行拓扑，因此上述账本只能定性换算到 B200/B300/GB200 NVL72 档位；材料亦未给出 NVFP4 等低精度采样下的稳定性讨论，采样稳定性需单独验证，不能把量化收益直接计入 KV 预算。</p>\n<table class=\"mini\"><thead><tr><th>账本项</th><th>结算口径</th><th>失效触发</th></tr></thead><tbody><tr><td>权重常驻</td><td>按档位与并行切分固定占用</td><td>切分方式未定，无法换算</td></tr><tr><td>KV 分页</td><td>批内最长序列 × 并发副本</td><td>尾部样本抢占、换出重算</td></tr><tr><td>激活峰值</td><td>批大小 × 最长序列</td><td>批越大，尾部风险越高</td></tr><tr><td>过滤损耗</td><td>被剔除候选的已耗 KV</td><td>阈值过高，有效产出率下降</td></tr></tbody></table>\n<p>工程判断落在调度侧而非容量侧：既然方法层面的改进在同等算力下比堆叠数据与模型规模更稳定，那么 KV 复用与批调度带来的收益应优先于提升算力档位。具体做法是把长尾样本从主批剥离，单独走小并发通道，主批按分页块回收短样本 KV；奖励评估阶段以提示词为键做前缀缓存，命中则复用，未命中则按变长输入重新分块。代价是调度器复杂度上升与页表元数据占用增加，收益是批完成率可预测、尾部延迟可归因。若过滤策略迁移到其他任务而未重新验证，方法层面的稳定性结论不再成立，此时账本必须按最坏长度重算，容量规划回到保守一侧。</p>\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-26\">二十六 · 连续批处理：把长尾从“整批墙钟”里剥出来</h3>\n<p>论文的rollout流程里，策略模型按提示词批次生成多条候选回复，生成长度呈长尾分布。若沿用静态批处理——整批等最慢那条序列结束才释放槽位——那么一条超长样本会把整批的完成时间拉长到它的长度量级，其余已完成序列占着KV显存空转。连续批处理（iteration-level scheduling）的机制是：每步解码后检查序列是否命中EOS或达到长度上限，命中即退出并立刻从等待队列补入新请求，使批内序列数在时间轴上保持填充。对RLHF rollout而言，这直接改变单位算力的有效样本产出：同一块显存不再被已完成序列的KV长期占用。</p>\n<p>代价可以写成显式的墙钟分解。设批内第 $i$ 条序列长度为 $L_i$，批大小为 $B$，单步解码耗时为 $t_{\\text{step}}(B)$，则静态批的批完成时间为</p>\n<div class=\"formula\">$$T_{\\text{static}} = t_{\\text{step}}(B)\\cdot \\max_i L_i,\\qquad T_{\\text{cont}} \\approx t_{\\text{step}}(B)\\cdot \\frac{\\sum_i L_i}{B}$$</div>\n<p>两者之比就是长尾带来的浪费系数。长尾越重、$B$ 越大，静态批的浪费越显著；而连续批把浪费压到接近平均长度。代价转移到调度侧：每步都要做一次退出/补入判定，补入新请求会触发其前缀KV的预填充，若前缀未命中缓存则形成一次短促的计算尖峰，表现为步间延迟抖动。工程判断是：rollout引擎应把“批完成率”与“尾部延迟”分开监控，前者看吞吐，后者看抖动来源。举例：一批32条候选回复中若有一条长度是均值的数倍，静态批下该批的墙钟被这条样本独占，连续批则让其余31条提前释放显存并补入下一批提示词，长尾样本单独在末尾收尾——它仍然慢，但不再绑架整批。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-27\">二十七 · Chunked prefill：把预填充切碎，填进解码的空隙</h3>\n<p>连续批处理解决了“等最慢”，但没有解决“新请求的前缀预填充一次性吃掉整个步”。一个长提示词的prefill是计算密集的大块，若整块插入解码步，会让同批正在解码的序列集体停顿一个长步，尾延迟出现尖刺。chunked prefill的机制是把预填充按token切块，每步只处理一块，与解码token混合编排进同一个批，使每步的计算量趋于均匀。对奖励模型评估阶段尤其关键：变长输入需要前缀共享与KV复用，切块让长输入的prefill可以分步摊平，而不是在评估队列里制造一个不可打断的长事务。</p>\n<p>切块粒度的取舍是显存与延迟的对偶。块越小，步间越平滑、尾延迟越可控，但每块都要重读一次权重与KV，权重带宽的摊销变差；块越大，摊销好、吞吐高，但单步变长、抖动回归。设块大小为 $C$，单步有效计算为 $C$ 个token的prefill加若干解码token，则单步时间的上界由 $\\max(\\text{prefill}(C), \\text{decode}(B_{\\text{dec}}))$ 决定，调度器的目标就是让这两项接近。代价体现在显存侧：切块要求为每个在途prefill保留中间状态（部分KV与注意力工作区），在途prefill越多，这部分预留越大。举例：一条数万token的长提示进入评估队列，若不切块，它会独占数个解码步的时间；切块后它被摊到几十步里，每步只多出一个小块，解码序列的步间延迟几乎不变，代价是这批评估的整体完成时间略长——这是用少量吞吐换尾延迟的典型交易。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-28\">二十八 · 优先级与抢占：让“新鲜度”成为一等调度维度</h3>\n<p>论文的异步流水线里，权重同步点决定样本新鲜度，进而影响off-policy程度与训练稳定性。这条结论在调度层的直接含义是：rollout请求不是同质的，靠近权重同步点的样本价值更高，远离同步点的样本可能生成完就已过期。优先级调度因此不能只按到达顺序，而应按“样本对当前策略的时效价值”排序；抢占则是它的兜底手段——当高优先级请求到达而显存不足时，驱逐低优先级序列，释放其KV，待其重新被调度时再恢复。</p>\n<p>抢占的代价必须显式记账。驱逐一条序列丢失其KV，恢复时要么重算prefill，要么依赖前缀缓存命中。设被驱逐序列长度为 $L$、前缀缓存命中率为 $h$，则恢复代价近似为</p>\n<div class=\"formula\">$$T_{\\text{resume}} \\approx (1-h)\\cdot t_{\\text{prefill}}(L) + t_{\\text{decode}}(L_{\\text{remain}})$$</div>\n<p>若 $h$ 高，抢占近乎免费；若前缀未命中，抢占就是把已付出的计算扔掉重来，吞吐直接受损。工程判断是：抢占策略必须与前缀KV复用绑定设计，否则优先级机制会在高负载下变成吞吐黑洞。举例：权重同步前一刻，调度器把仍在生成的低优先级长尾样本驱逐，腾出显存给新一批提示词；这些长尾样本在同步后按新权重重新生成，其旧KV若命中前缀缓存则只补剩余部分，若不命中则整条重算——这一步的代价决定了“追新鲜度”是否划算。论文强调方法层面的过滤与调度策略收益高于单纯扩批量，正对应此处：调度决策的质量比堆算力更能改变单位算力的有效偏好数据量。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-29\">二十九 · 分离式预填/解码：两种截然不同的负载不该挤在一个池子里</h3>\n<p>预填充是计算密集、对权重带宽敏感的大块矩阵乘；解码是访存密集、逐token串行、对KV带宽敏感。把两者混在同一组GPU上，chunked prefill只能缓解而不能消除互相干扰：prefill块会周期性拉长解码步。分离式（disaggregated）预填/解码的机制是把两阶段放到不同的GPU池，预填充池产出KV，经高速互联传给解码池，解码池专注低延迟逐token生成。在Blackwell NVL72的机架内，NVLink 5的高带宽使KV传输的代价可控，这是该架构可行的前提；若跨机架走低速链路，KV搬运会成为新的瓶颈。</p>\n<p>代价换算是带宽与显存的联合账。设每token每层的KV字节数为 $s$，层数 $N_l$，序列长度 $L$，则单条序列的KV体量为 $s\\cdot N_l\\cdot L$；预填充池到解码池的传输时间由该体量除以有效互联带宽决定。分离的收益是解码池的步间延迟方差大幅下降——没有prefill尖峰插入；代价是KV传输占用互联带宽、且两池的容量必须分别规划，任一池成为瓶颈都会让另一池闲置。对RLHF rollout的具体含义：生成阶段（策略模型批量生成）适合解码池的稳定低延迟，奖励评估阶段的长输入prefill适合预填充池的高计算密度，两段负载形态不同，分开编排比混批更易压尾延迟。举例：评估队列涌入一批超长输入时，预填充池被占满而解码池仍在稳定产出候选回复，两段互不阻塞；若混在同一池，长输入的prefill块会把正在解码的候选回复集体拖慢，尾部延迟直接传导到批完成率。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-30\">三十 · 时延与吞吐的取舍面，以及尾延迟怎么压</h3>\n<p>把上述机制放到一张取舍面上：批越大，权重读取与KV带宽摊销越好，吞吐越高，但单步变长、尾延迟风险上升；chunked prefill越小，尾延迟越平滑，但摊销变差；抢占越激进，样本越新鲜，但重算代价侵蚀吞吐；分离越彻底，两段延迟越可控，但KV传输与容量规划成本上升。论文的扩展性结论给这张面加了一条约束：数据与模型规模的边际收益递减，意味着靠扩批量、扩模型档位换吞吐的回报在变薄，而调度与方法层面的改进在同等算力下更稳定。因此容量规划应把尾部延迟与批完成率作为一等指标，而不是只盯平均吞吐。</p>\n<p>尾延迟的压制要落在具体机制上，而非笼统的“优化调度”。三条可操作的路径：其一，按长度分桶路由，把长尾样本隔离到专用池，避免它们与短样本共享批的墙钟；其二，对奖励评估的变长输入强制前缀共享与KV复用，把重复计算从评估路径上摘掉，这是论文明确指出的吞吐杠杆；其三，对过滤阈值做吞吐核算——阈值过高会剔除大量样本、降低单位算力的有效产出，阈值过低则让高噪声样本进入偏好数据，两者都在改变有效样本产出率，调度器应把过滤后的有效样本数而非原始生成数作为吞吐口径。举例：监控发现批完成率下降而平均步时未变，说明瓶颈在长尾样本的收尾段而非稳态解码，此时应检查分桶路由是否把长尾正确隔离，以及评估段的前缀缓存命中率是否因输入变长而下降。</p>\n<p>最后落到一个工程判断：在材料未给出硬件档位、并行拓扑与量化方案的条件下，任何把论文结论直接换算成Blackwell吞吐数字的做法都缺少定量依据；可做的是把调度参数（批大小、chunk粒度、抢占阈值、分桶边界）作为容量规划的显式变量，用尾部延迟与有效样本产出率两个指标闭环调节。NVFP4等低精度采样下的稳定性需单独验证，因为它改变的是生成分布本身，而调度只能改变分布被采样的效率——两者不可互相替代。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-31\">三十一 · 长尾样本与奖励评估耦合下的批调度边界</h3>\n<p>连续批处理与 chunked prefill 在 RLHF rollout 中的收益并非无条件成立：策略模型批量生成候选回复时，生成长度呈长尾分布，少数超长样本拖慢整批完成时间；这些样本随后进入奖励模型或验证器，变长输入若不做前缀共享与 KV 复用，重复计算会显著降低吞吐。批越大，单位时间吞吐越高，但尾部延迟风险同步放大，因为整批完成时间由最慢样本决定。设批内第 <i>i</i> 条样本的生成时延为 <i>t<sub>i</sub></i>，批完成时延近似 <i>T</i><sub>batch</sub> = max<sub>i</sub>(<i>t<sub>i</sub></i>) + <i>t</i><sub>reward</sub>(<i>y<sub>i</sub></i>)，其中奖励评估时延随回复长度增长。这意味着调度器若只按平均长度装箱，长尾样本会把批完成率压到不可接受的水平。</p>\n<p>失效条件集中在三处：其一，过滤阈值过高时，大量候选被打回，有效样本产出率下降，单位算力吞吐随之走低，批调度再优也无法弥补；其二，异步流水线中权重同步点决定样本新鲜度，同步间隔过长会提高 off-policy 程度，同步过频则打断批的连续性，二者都与批大小耦合；其三，奖励评估阶段的前缀复用若被长尾样本的变长输入打散，KV 复用命中率下降，显存带宽成为瓶颈而非算力。可用一张小表刻画取舍：</p>\n<table class=\"mini\"><thead><tr><th>调度选择</th><th>吞吐</th><th>尾延迟</th><th>主要代价</th></tr></thead><tbody><tr><td>大批 + 连续批处理</td><td>高</td><td>高</td><td>长尾样本拖慢整批，KV 占用上升</td></tr><tr><td>小批 + chunked prefill</td><td>中</td><td>低</td><td>前缀复用碎片化，调度开销占比升高</td></tr><tr><td>优先级 + 抢占</td><td>中</td><td>可控</td><td>被抢占样本重算，浪费已生成 token</td></tr></tbody></table>\n<p>工程判断是：在材料未给出具体硬件档位与并行拓扑的前提下，rollout 引擎应把尾部延迟与批完成率作为一等监控指标，用优先级与抢占保护短样本、把超长样本隔离到独立队列，并以过滤阈值调节有效样本产出率，而非单纯扩大批量或提升算力档位；方法层面的过滤与调度策略在同等算力下比堆叠数据与模型规模更稳定，这一结论直接约束了批调度的设计取向。</p>\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-32\">三十二 · 切分维度与RLHF三段流水线的耦合</h3>\n<p>在Blackwell上部署该论文所描述的RLHF rollout引擎，并行切分不是一套静态配置，而是被三段流水线的负载形态反向决定。策略生成段是自回归解码，KV cache随序列线性增长，天然倾向按序列维度切分；奖励评估段是一次前向打分，输入变长且前缀高度共享，倾向按前缀与批维度切分；偏好过滤段几乎不占算力，却是同步点。TP（张量并行）把单层权重与激活沿隐藏维切开，每层后接一次All-Reduce，通信量与激活大小成正比，适合放在节点内NVLink域；EP（专家并行）只在MoE策略模型上出现，路由结果决定token去向，需要All-to-All交换；PP（流水并行）把层段分到不同设备，代价是流水气泡与激活驻留；DP（数据并行）复制权重、切分请求，梯度侧才需要规约，推理侧主要是请求级负载均衡。论文材料未给出并行拓扑，但“批量生成调度与KV复用策略决定吞吐上限”这一判断意味着：切分方案必须先服从长尾生成段的KV驻留，再考虑评估段的变长批效率。</p>\n<p>一个具体机制是：生成段按TP=8把每层矩阵乘切到8张SM，单次解码步的All-Reduce消息量为 <span>2×(batch×hidden×dtype_bytes)</span>，在NVFP4权重、BF16激活的混合精度下，激活规约仍走BF16，消息量不因权重压缩而缩小。这就是精度优化与通信代价脱钩的典型位置——量化省的是显存与MMA吞吐，不省集合通信字节。</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(T_{\\text{MMA}},\\; T_{\\text{comm}}\\right) + T_{\\text{launch}},\\qquad T_{\\text{comm}} = \\frac{2\\,B\\,H\\,s}{W_{\\text{nvl}}} + \\alpha$$</div>\n<p>其中B为批内token数，H为隐藏维，s为字节宽度，W_nvl为NVLink 5单链路带宽，α为内核启动与同步开销。解码阶段B小、H固定，T_MMA很短，T_comm与α占比上升，TP度数越高越容易被通信主导；预填阶段B大，T_MMA主导，TP才真正划算。这解释了为什么分离式预填/解码在Blackwell上不是可选优化而是拓扑前提。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-33\">三十三 · NVLink 5与NVSwitch：域内带宽的可用边界</h3>\n<p>GB200/GB300 NVL72把72颗GPU放进同一个NVLink域，NVSwitch承担全互联交换。对推理而言，这个域的意义不是“带宽大”这种定性描述，而是决定了哪些集合通信可以留在域内、哪些必须出域。TP与EP的All-Reduce/All-to-All若落在NVLink域内，延迟由交换级数与链路带宽共同决定；一旦跨域走InfiniBand或以太，消息要经历协议栈与拥塞控制，尾延迟显著抬升。因此工程判断是：TP组不跨域，EP组尽量不跨域，PP组可以跨域因为层间只传激活、频率低、消息量小。</p>\n<p>具体机制上，NVSwitch的无阻塞特性使All-to-All的完成时间近似由最慢接收方决定，而非链路数。EP场景下每个token被路由到若干专家，All-to-All的发送缓冲按token数×隐藏维分配，MoE层越宽、专家越多，单层交换的消息量越大。代价体现在显存与带宽两侧：All-to-All需要为在途token预留通信缓冲，这部分显存不能给KV cache；同时交换期间SM空转，若不用通信-计算重叠，MoE层的有效算力利用率被交换时间稀释。一个具体例子：GB200 NVL72上跑MoE策略模型做rollout，若EP组跨了两个NVLink域，All-to-All的尾延迟会直接反映为解码步的抖动，长尾样本的批完成时间被进一步拉长——这与论文强调的“长尾样本拖慢整批完成时间”在通信层叠加。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-34\">三十四 · All-Reduce与All-to-All的代价结构差异</h3>\n<p>两类集合通信的代价随规模变化的斜率不同，这决定了切分策略的取舍。All-Reduce（TP后接的规约）采用环形或树形算法，消息量随参与度数近似线性增长，延迟随度数对数增长；在NVLink域内，TP=8的All-Reduce延迟通常被隐藏在MMA之后，但解码阶段MMA太短，隐藏不住。All-to-All（EP路由）的消息量随token数与专家数乘积增长，且是稀疏、非对称的，容易出现热点专家导致的链路不均衡。工程上判断通信是否成为瓶颈，不看平均带宽利用率，而看两个量：集合通信时间占解码步时间的比例，以及批内最慢序列的通信等待。</p>\n<div class=\"formula\">$$\\eta_{\\text{comm}} = \\frac{T_{\\text{AR}} + T_{\\text{A2A}}}{T_{\\text{step}}},\\qquad \\text{瓶颈判据：}\\ \\eta_{\\text{comm}} &gt; 1-\\frac{T_{\\text{MMA}}}{T_{\\text{step}}}$$</div>\n<p>代价落到吞吐上：当η_comm越过判据，增加批大小不再提升吞吐，因为每步时间被通信固定住，批内token摊薄不了固定开销。这正是论文“单纯扩大批量收益递减”的通信侧解释之一。具体例子：奖励评估段若用TP=4做变长批打分，前缀共享使有效批内token数远大于生成长度，T_MMA足够长，η_comm低，TP划算；而同一拓扑搬到生成段，批内token少、步长短，η_comm高，此时应降低TP度数、改用DP扩请求并行度，把通信从关键路径上挪走。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-35\">三十五 · NIXL传输：KV与权重的跨节点搬运</h3>\n<p>NIXL面向的是显存到显存的点对点传输，绕过主机内存与通用协议栈，适合KV cache迁移、权重同步与分离式部署中的状态搬运。在该论文的异步流水线里，权重同步点决定样本新鲜度与off-policy程度，而同步本身是一次跨节点的大块传输。NIXL的价值在于把这次传输从“停等”变成可与生成重叠的后台操作：新权重在旧权重仍服务在途请求时预取到目标节点显存，切换点只做指针交换。代价是显存双份驻留——新旧权重同时在场，加上KV cache，显存预算被挤压；在B200/B300的HBM容量下，这决定了能同时容纳多少并发序列。</p>\n<p>KV复用与NIXL的组合是评估段的关键机制：前缀共享要求把策略生成段产生的前缀KV保留下来供奖励模型复用，若两段不在同一节点，就需要NIXL把前缀KV块搬到评估节点。传输量与前缀长度×层数×KV头维度成正比，长前缀样本的搬运成本高。工程判断是：前缀KV的复用收益必须大于搬运成本才值得跨节点共享，否则应在同节点内做前缀共享、跨节点只传打分结果。具体例子：长尾样本的超长前缀若跨节点搬运，其传输时间可能超过重新计算的时间，此时“复用”反而拖慢评估段——这要求调度器按前缀长度做搬运/重算的二元决策，而不是无条件复用。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-36\">三十六 · 通信何时成为瓶颈：三个可观测判据</h3>\n<p>把“通信是不是瓶颈”落成可监控的量，而不是靠经验判断。第一个判据是解码步时间的方差：若批完成时间的抖动主要来自集合通信等待而非MMA，尾部延迟监控应拆出通信等待这一项。第二个判据是SM空闲率与NVLink利用率的组合：SM空闲高而链路利用率低，说明是同步与启动开销；两者同时高，说明是真实带宽受限。第三个判据是批大小扫描曲线：吞吐随批大小上升后提前走平，走平点对应的批大小就是通信主导的拐点，容量规划应以此为批上限参考，而不是按显存上限堆批。</p>\n<ul>\n<li>生成段：批内token少、步长短，TP度数越高越易通信主导，优先DP扩并发、TP限在NVLink域内。</li>\n<li>评估段：变长批、前缀共享使MMA时间长，TP可适度提高，但前缀KV跨节点搬运需与重算比较。</li>\n<li>MoE策略模型：EP的All-to-All是热点，需通信-计算重叠与专家负载均衡，否则单层交换稀释有效算力。</li>\n<li>权重同步：NIXL预取与指针切换可把同步代价移出关键路径，代价是显存双份驻留挤压KV预算。</li>\n</ul>\n<p>论文材料未给出硬件档位与并行拓扑，因此上述判据只能定性落地：把η_comm、批大小拐点、前缀搬运/重算比三项纳入rollout引擎的监控面板，与论文强调的尾部延迟、批完成率、有效样本产出率并列。方法层面的过滤策略在同等算力下更稳定的结论，在通信侧的含义是：与其把算力堆到更高TP度数换来被通信吃掉的步时间，不如把预算花在减少无效样本上——过滤阈值提高会降低吞吐，但降低的是被长尾与通信双重拖慢的那部分吞吐。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-37\">三十七 · 拓扑决策与容量规划的耦合</h3>\n<p>最终落到一个工程判断：在Blackwell上，RLHF rollout的并行拓扑应由“生成段通信占比”与“评估段前缀复用率”两个观测量共同决定，而不是照搬预训练的训练拓扑。生成段若η_comm高，降TP、增DP、把请求打散到更多NVLink域外的副本，用请求级并行替代张量级并行；评估段若前缀复用率高，保持TP在域内、用NIXL做同域KV块搬运，避免跨域。MoE策略模型的EP组必须落在单一NVLink域内，跨域All-to-All的尾延迟会直接污染长尾样本的批完成时间。容量规划上，批上限取通信拐点而非显存上限，KV预算扣除NIXL权重双份驻留与All-to-All通信缓冲后的余量才是可用并发数。</p>\n<p>这套判断与论文的扩展性结论对齐：数据与模型规模的边际收益递减，在推理侧表现为批大小与TP度数越过拐点后吞吐不再增长；方法层面的过滤与调度改进在同等算力下更稳定，在通信侧表现为减少无效样本比提高并行度更能守住SLO。材料未给出NVFP4采样稳定性与具体拓扑，因此拓扑决策必须配合实测的η_comm与拐点扫描，不能由论文结论直接换算为部署参数。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-38\">三十八 · 并行切分在 rollout 流水线上的失效边界</h3>\n<p>论文没有给出并行拓扑，这恰恰是它最诚实的部分：RLHF 的推理流水线不是单一模型的推理，而是策略模型批量生成、奖励模型或验证器变长评估、过滤筛选三段串联。三段对并行的偏好彼此冲突——生成段偏好 DP/TP 以摊薄权重读取，评估段因变长输入与前缀共享更依赖 EP 与 KV 复用，而两段之间的样本交接是 All-to-All 型的数据重排。当 TP 组跨出 NVLink 5 单域、落到 NVSwitch 之外的跨机柜链路时，每层 All-Reduce 的时延不再被计算掩盖，生成段的批完成时间被通信拖长；而长尾样本使批内最慢序列决定整批同步点，通信代价被尾部放大而非平均摊薄。可写的判据是：单批通信时间占比</p>\n<div class=\"formula\">$$T_{\\text{comm}}/T_{\\text{batch}} \\approx \\frac{2(N-1)}{N}\\cdot\\frac{S}{B_{\\text{link}}}\\Big/\\Big(\\frac{2(N-1)}{N}\\cdot\\frac{S}{B_{\\text{link}}}+T_{\\text{comp}}\\Big)$$</div>\n<p>其中 $S$ 为每层激活字节数、$N$ 为 TP 度、$B_{\\text{link}}$ 为有效链路带宽。当该比值随 $N$ 上升而越过计算占比，扩 TP 就是负收益，此时应退回 DP 加 EP，把跨域流量压到样本交接这一次 All-to-All 上。</p>\n<table class=\"mini\"><thead><tr><th>切分</th><th>受益环节</th><th>失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>TP</td><td>生成段权重摊薄</td><td>跨 NVLink 域、批小</td><td>每层 All-Reduce 时延</td></tr><tr><td>EP</td><td>评估段变长输入</td><td>专家负载倾斜</td><td>All-to-All 带宽与抖动</td></tr><tr><td>PP</td><td>大模型单机放不下</td><td>流水气泡随批减小</td><td>激活驻留显存</td></tr><tr><td>DP</td><td>吞吐线性扩展</td><td>权重同步点频繁</td><td>NIXL 传输与新鲜度</td></tr></tbody></table>\n<p>NIXL 在这里的角色不是加速卡间集合通信，而是把过滤后的偏好对从 rollout 引擎搬到权重同步点：它绕开主机内存做 GPU 直传，省掉一次落盘与拷贝，但传输量与过滤阈值直接挂钩——阈值抬高、有效样本变少，单位算力产出的偏好对下降，传输反而成为流水线里相对更重的一环。真正该监控的是尾部延迟与批完成率：长尾样本在生成与评估两段同时拉长批同步点，通信瓶颈往往不在均值带宽，而在最慢那条序列所触发的同步等待。材料未给出 NVFP4 采样稳定性，低精度下若采样分布偏移，过滤阈值需重标定，否则有效样本产出率的下降会被误判为通信问题。</p>\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-39\">三十九 · 精度塌陷：低精度采样在长尾上的静默失效</h3>\n<p>在 Blackwell 上把 rollout 引擎推到 NVFP4 或 FP8 采样，最先出问题的不是均值，而是分布尾部。策略模型按批量调度生成候选回复，生成长度呈长尾分布，少数超长样本在低精度下经历更多次自回归迭代，舍入误差沿 token 序列累积，最终表现为重复、截断或语义漂移。论文材料明确指出未给出 NVFP4 等低精度采样下的稳定性讨论，采样稳定性需单独验证——这句话的工程含义是：精度塌陷不会在平均奖励上暴露，只会在尾部样本上暴露，而尾部样本恰好是拖慢批完成时间的那一批。</p>\n<p>诊断机制应当落在逐 token 的 logprob 漂移上。对同一提示词分别用高精度参考路径与低精度部署路径采样，记录每步的 KL 增量：</p>\n<div class=\"formula\">$$\\delta_t=\\mathrm{KL}\\left(\\pi_{\\text{ref}}(\\cdot|x,y_{&lt;t})\\,\\|\\,\\pi_{\\text{low}}(\\cdot|x,y_{&lt;t})\\right),\\qquad \\Delta=\\sum_{t=1}^{T}\\delta_t$$</div>\n<p>当 Δ 随生成长度 T 单调上升且斜率在长尾区间陡增时，判定为精度塌陷而非采样噪声。代价方面：逐 token KL 需要双路径并行，显存上等于把 KV cache 翻倍，吞吐减半；工程折中是按批抽样百分位路径做抽检，把双路径开销压到批级别的个位数百分比。具体例子：一批 64 条候选回复中，长度超过某阈值的少数样本若 Δ 显著高于短样本，则不应调高过滤阈值掩盖问题——过滤阈值过高本身就会降低单位算力下的吞吐，正确动作是回滚该批次的低精度采样开关，并对长尾区间单独启用高精度路径。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-40\">四十 · OOM 与批抖动：批大小与长尾的耦合震荡</h3>\n<p>OOM 在 rollout 引擎里通常不是稳态问题，而是批抖动问题。批量生成调度按批大小与并发度调节，批越大吞吐越高但尾部延迟风险越大；当批内混入超长样本，KV cache 随生成长度线性增长，显存峰值由批内最长序列而非平均序列决定。奖励评估阶段输入变长，需要前缀共享与KV复用降低重复计算，但前缀共享的收益依赖批内前缀重叠度——一旦调度器为了填满批而混入前缀差异大的请求，KV 复用率下降，显存与带宽同时吃紧，形成“批越大→复用率越低→显存峰值越高→触发 OOM→回退小批→吞吐下降”的震荡环。</p>\n<p>定位手段是把批完成率与显存峰值放在同一时间轴上对齐。伪代码思路：</p>\n<ul>\n<li>记录每个批的 max_seq_len、前缀重叠率、KV 复用命中率、显存峰值四个量；</li>\n<li>当显存峰值超过水位线而批完成率同步下跌时，判定为长尾耦合而非单纯容量不足；</li>\n<li>回滚动作是切分批次：按预测生成长度分桶，长尾样本单独成批并配高精度路径，短样本批维持大 batch 吃吞吐。</li>\n</ul>\n<p>代价判断：分桶会牺牲一部分批内前缀共享，KV 复用命中率下降，单位 token 的带宽开销上升；但不分桶则 OOM 回退造成的吞吐损失更大。论文强调方法设计对扩展性的影响大于单纯堆叠数据与模型规模，这里的“方法”在工程上就体现为分桶调度策略而非扩容。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-41\">四十一 · 尾延迟：生成与评估两段的耦合瓶颈</h3>\n<p>论文的失败模式描述很直接：长尾样本在生成与评估两段都拖慢批完成时间，需要监控尾部延迟与批完成率定位瓶颈。关键在于这两段的长尾不是同一个分布——生成长尾由自回归停止条件决定，评估长尾由变长输入的前缀共享效率决定。若只监控端到端 P99，无法区分是生成段还是评估段贡献了尾部。</p>\n<p>分段埋点是必需的：在生成段出口与评估段入口各打一个时间戳，得到两段各自的尾延迟分布。系统代价上，评估段的尾延迟往往被低估，因为奖励模型或验证器的变长输入若前缀共享不足，重复计算会显著降低吞吐，而重复计算在监控上表现为“评估段 P99 抬升但均值不变”。具体例子：同一批候选中，前缀重叠率低的子集在评估段耗时显著高于重叠率高的子集，此时瓶颈在调度器的批组装策略而非奖励模型本身，回滚动作是调整批组装的前缀亲和性排序，而不是换模型或加卡。</p>\n<p>容量规划上，尾部延迟应作为独立预算项而非均值延迟的余量。论文材料未给出具体硬件档位与并行拓扑，因此尾延迟预算无法直接换算为 Blackwell 档位下的绝对毫秒数，只能以批完成率与 P99 的相对关系做容量判断：当 P99 抬升伴随批完成率下降，说明长尾已进入容量约束区，此时扩容的边际收益低于调度策略调整。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-42\">四十二 · 静默降级：过滤阈值与权重同步点的隐性代价</h3>\n<p>最危险的失败模式是不报错的降级。偏好数据过滤阈值直接影响有效样本产出率，阈值过高会降低单位算力下的吞吐；但阈值调高在监控上表现为“奖励均值上升、样本量下降”，看起来像质量改进，实际是有效偏好数据量缩水。异步流水线中权重同步点决定样本新鲜度，进而影响 off-policy 程度与训练稳定性；同步点拉长会提高吞吐，但样本新鲜度下降带来的 off-policy 偏移不会立刻反映在损失上，而是延后若干轮才表现为对齐质量退化。</p>\n<p>监控这两个量的机制是产出率与新鲜度的双指标看板：有效样本产出率 = 通过过滤的偏好对数 / 单位算力，新鲜度 = 样本生成时刻与权重同步时刻的间隔分布。判定规则是：产出率上升但新鲜度分布右移，说明吞吐是用 off-policy 换来的，属于静默降级；产出率下降但奖励均值上升，说明过滤阈值在掩盖精度或评估问题。回滚动作分别是收紧同步点间隔与回调过滤阈值，两者都需要在方法层面重新验证——论文的稳定性结论依赖具体过滤策略，迁移到其他任务需重新验证。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-43\">四十三 · 回滚与容量判断：把失败模式接进 SLO</h3>\n<p>回滚不是恢复到上一个版本那么简单，而是要把失败模式映射到可执行的开关上。工程上应维护一组与论文三条线对应的回滚面：精度面（低精度采样开关与长尾区间的高精度路径）、调度面（批大小、分桶策略、前缀亲和性排序）、方法面（过滤阈值、权重同步点间隔）。每个回滚面绑定一个触发指标：精度面对应逐 token KL 漂移，调度面对应批完成率与显存峰值，方法面对应有效样本产出率与新鲜度分布。</p>\n<p>容量判断的落点是：论文报告 RLHF 的扩展性在数据、模型与方法三个维度上均存在收益递减，方法层面的改进在同等算力下比单纯增加数据或模型规模更稳定。对 Blackwell 部署的直接含义是，当尾延迟与批完成率同时恶化时，优先调整调度与方法面的回滚面，而非提升算力档位；扩容只应在回滚面全部收敛后仍不满足 SLO 时启用。材料未给出具体数字与硬件档位，直接引用其结论做容量规划会缺少定量依据，因此监控指标必须自行补齐，且长尾样本与奖励评估耦合的失败模式缺少定量分析这一局限，意味着尾延迟预算需要按保守侧设定并随监控数据滚动修正。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-44\">四十四 · 长尾耦合下的静默降级：从批完成率到回滚闸门</h3>\n<p>RLHF rollout 的失效很少以硬报错的形式出现，更多表现为“看起来还在跑、但单位算力产出的有效偏好对在下降”。论文把生成与评估拆成两段后，真正的耦合点在于：策略模型按批调度生成候选回复，生成长度呈长尾分布，少数超长样本拖慢整批完成时间；这些样本随后进入奖励模型或验证器，变长输入若不能前缀共享与 KV 复用，重复计算会进一步放大尾部代价。于是批完成率与尾部延迟同时恶化，而调度器仍按原批大小继续投放新请求，形成批抖动——批越大吞吐名义值越高，但尾部风险与显存驻留同步上升。诊断上应把“批完成率”与“P99 生成长度”作为一对联合指标：当批完成率下降而中位生成长度不变时，问题几乎必然出在长尾与评估段的 KV 复用失效，而非策略模型本身变慢。</p>\n<p>精度塌陷与静默降级是另一类边界。材料未给出 NVFP4 等低精度采样下的稳定性讨论，因此低精度 rollout 的采样稳定性必须单独验证：奖励分数分布若在量化前后出现系统性偏移，过滤阈值就会失效——阈值过高会降低单位算力下的吞吐，阈值过低则让高噪声样本进入异步流水线，权重同步点带来的样本新鲜度下降会放大 off-policy 程度。一个可操作的判据是把有效样本产出率写成过滤阈值 τ 的函数：</p>\n<div class=\"formula\">$$R_{\\text{eff}}(\\tau)=\\frac{N_{\\text{pass}}(\\tau)}{T_{\\text{batch}}+T_{\\text{eval}}}\\cdot\\frac{1}{C_{\\text{GPU}}}$$</div>\n<p>其中 $N_{\\text{pass}}$ 为过阈样本数，$T_{\\text{batch}}$ 受长尾支配，$T_{\\text{eval}}$ 受变长输入与前缀复用率支配。τ 上调时 $N_{\\text{pass}}$ 下降但 $T_{\\text{eval}}$ 未必下降，$R_{\\text{eff}}$ 可能不升反降——这正是“方法层面改进在同等算力下更稳定”这一结论在工程上的落点：调阈值不是免费的，必须与批调度联动。</p>\n<p>OOM 在 rollout 引擎里通常不是模型权重问题，而是长尾样本把 KV 驻留推到峰值：批内最长的几条回复决定了该批的显存高水位，前缀共享只能削减重复前缀部分，无法压缩生成本身的增量 KV。定位手段是给每个批打上“最长样本长度 / 批大小 / 前缀复用率”三元组，OOM 前必然出现该三元组的单调漂移。回滚闸门应分级：一级回滚批大小与并发度，二级回滚过滤阈值到上一稳定值，三级回滚权重同步节奏以恢复样本新鲜度。表格给出三类失败模式的判别信号与首选动作：</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>判别信号</th><th>首选动作</th></tr></thead><tbody><tr><td>批抖动</td><td>批完成率降、中位长度不变、P99 升</td><td>降批大小、拆长尾批</td></tr><tr><td>精度塌陷</td><td>奖励分数分布偏移、过阈率突变</td><td>回滚量化档位、重验 τ</td></tr><tr><td>静默降级</td><td>有效样本产出率缓降、off-policy 升</td><td>回滚同步节奏、收紧 τ</td></tr></tbody></table>\n<p>尾延迟监控必须落在容量规划里而非事后告警：论文强调长尾样本在生成与评估两段都拖慢批完成时间，材料又未给出具体硬件档位与并行拓扑，因此把论文结论直接换算成 Blackwell 部署的吞吐与显存代价会缺少定量依据。工程判断是：在档位未定的情况下，先用批完成率与有效样本产出率两条曲线做容量上限的保守估计，把长尾监控作为 SLO 的一部分而非可选项；任何一次 τ 或批大小的调整都应视为一次可回滚的发布，而不是运行期随手拧的参数。</p>\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-45\">四十五 · 论文口径的边界：哪些量可换算，哪些不可换算</h3>\n<p>这篇论文的扩展性结论建立在数据规模、模型规模、方法设计三条线上，报告的是收益递减的相对形态，而不是某一台机器上的绝对吞吐。把它搬到 Blackwell 部署语境，第一步是分清两类量：一类是<strong>可迁移的相对量</strong>，例如“方法层面改进在同等算力下比堆数据更稳定”这一排序关系，它只依赖算力预算的定义，与具体硬件无关；另一类是<strong>不可迁移的绝对量</strong>，例如单位时间有效偏好对产出、批完成时间、尾部延迟分位数，这些量由硬件档位、并行拓扑、量化方案共同决定，论文材料明确未给出硬件档位与并行拓扑，因此任何把论文结论直接折算成 B200 或 GB200 NVL72 上 token/s 的做法都是越界。</p>\n<p>工程上可操作的口径是：把论文的结论当作<strong>容量规划的约束方向</strong>而非数值输入。它告诉你优化优先级应落在过滤策略与批调度上，而不是单纯抬升算力档位；但它不告诉你批大小取多少、KV 复用能省下多少显存。这两件事必须在自己的硬件档位上实测。判断一个引用是否可比，可以看它是否同时声明了五项：模型与精度、硬件档位与并行切分、batch 与并发上限、指标定义（TTFT/TPOT/吞吐/显存/功耗中的哪些）、以及负载长度分布。缺任何一项，跨条目比较就失去意义。</p>\n<div class=\"formula\">$$\\text{可比性} = \\mathbb{1}[\\text{model}\\wedge\\text{hw}\\wedge\\text{batch}\\wedge\\text{metric}\\wedge\\text{len-dist}]$$</div>\n<p>代价层面要记住一个不对称：论文的结论对<strong>吞吐方向</strong>敏感，对<strong>延迟绝对值</strong>不敏感。方法改进带来的稳定性提升，体现在单位算力下有效样本产出率的曲线上；而 TTFT 的绝对值取决于预填阶段在 Blackwell 上的 tcgen05 与 TMEM 利用效率，这一层论文完全没有触及。因此读这篇论文时，吞吐类结论可以借方向，延迟类结论只能借趋势。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-46\">四十六 · 硬件档位与 batch 口径：论文没给的，必须自己钉住</h3>\n<p>论文材料未给出硬件档位，这意味着它的“同等算力”是一个抽象预算单位。落到 Blackwell，档位差异直接改变结论的可比性：B200 单机与 GB200 NVL72 机架在显存容量、NVLink 5 域宽、可承载的并发批规模上不在一个量级，同一套批调度策略在两者上的尾部延迟表现会分叉。更关键的是精度档位——论文未讨论 NVFP4 等低精度采样下的稳定性，而采样稳定性会反过来影响过滤阈值的有效性：低精度采样若引入分布偏移，高阈值过滤会剔除更多样本，有效样本产出率下降，此时“方法改进更稳定”的结论需要在你的精度档位上重新验证。</p>\n<p>batch 与并发是两个必须分开记录的口径。batch 指单次前向中打包的序列数，受显存与 KV 容量约束；并发指同时在流水线中的请求数，受调度器与奖励评估阶段的处理能力约束。论文强调批量生成调度决定单位时间有效样本量，但没有给出批大小与并发的具体配比。工程上的做法是把二者作为二维网格扫描：固定并发、扫 batch，观察尾部延迟与批完成率；再固定 batch、扫并发，观察奖励评估阶段是否成为瓶颈。只有在这张网格上，论文的“长尾样本拖慢整批完成时间”才转化为可观测的指标。</p>\n<table class=\"mini\"><thead><tr><th>口径项</th><th>论文是否给出</th><th>Blackwell 部署必须补齐</th><th>缺失后果</th></tr></thead><tbody><tr><td>模型与精度</td><td>未给出量化方案</td><td>FP8/NVFP4 采样稳定性验证</td><td>过滤阈值失效，有效样本率失真</td></tr><tr><td>硬件档位</td><td>未给出</td><td>B200/B300/GB200 NVL72 分档实测</td><td>吞吐结论无法换算</td></tr><tr><td>batch/并发</td><td>未给出配比</td><td>二维网格扫描</td><td>尾部延迟归因错误</td></tr><tr><td>指标定义</td><td>未给出</td><td>TTFT/TPOT/吞吐/显存/功耗分列</td><td>跨条目数字不可比</td></tr></tbody></table>\n<p>一个具体例子：在同一 NVL72 域内，把 batch 从保守值抬到显存允许的上限，吞吐上升但长尾样本的批完成时间被拉长，奖励评估阶段因变长输入排队而积压，端到端有效样本产出反而下降。这正是论文所说“批越大吞吐越高但尾部延迟风险越大”的工程形态，而拐点位置只能靠实测确定。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-47\">四十七 · 指标口径：五个指标不能混成一句“更快”</h3>\n<p>TTFT 由预填阶段决定，在 Blackwell 上受 2-SM MMA 与 TMEM 占用影响；TPOT 由解码阶段的逐 token 步进决定，受 KV 读取带宽与批内序列数影响；吞吐是单位时间完成的 token 或样本数，与 batch 强相关但与延迟弱相关；显存由权重、KV cache 与激活共同占用，KV 复用策略直接改变其斜率；功耗在机架尺度上与利用率和精度档位相关。论文只给出扩展性趋势，未给出任何一项的绝对值，因此五项指标必须分列记录，任何把它们压缩成单一“加速比”的表述都会掩盖瓶颈位置。</p>\n<p>对这篇论文而言，最贴合的指标是<strong>单位算力有效偏好对产出率</strong>，它把生成吞吐、评估吞吐与过滤通过率三者耦合在一起：</p>\n<div class=\"formula\">$$\\text{Yield} = \\frac{N_{\\text{pass}}\\cdot \\bar{L}_{\\text{eff}}}{P_{\\text{compute}}\\cdot T_{\\text{batch}}}$$</div>\n<p>其中 $N_{\\text{pass}}$ 是通过过滤阈值的样本数，$\\bar{L}_{\\text{eff}}$ 是有效样本的平均信息量代理，$T_{\\text{batch}}$ 是批完成时间（由长尾样本决定而非均值）。这个式子的工程含义是：抬高过滤阈值会降低 $N_{\\text{pass}}$，但同时可能提升 $\\bar{L}_{\\text{eff}}$，净效应不确定；而 $T_{\\text{batch}}$ 由尾部而非均值主导，意味着优化均值吞吐对 Yield 的贡献有限。论文“阈值过高会降低单位算力下吞吐”的判断，正是这个式子在 $N_{\\text{pass}}$ 下降快于 $\\bar{L}_{\\text{eff}}$ 上升时的形态。</p>\n<p>具体例子：奖励评估阶段若不做前缀共享，变长输入的重复计算会让评估吞吐随输入长度方差增大而塌陷，此时 TTFT 看似正常，但批完成时间被评估段拖长，Yield 下降。监控应同时看尾部延迟分位数与批完成率，单看平均 TPOT 会漏掉这类瓶颈。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-48\">四十八 · 数字怎么读：三类不可比的提升</h3>\n<p>第一类不可比来自<strong>硬件档位替换</strong>。把 B200 上的吞吐数字与论文的抽象算力预算对齐，等于假设两者算力换算系数为 1，而材料未给出任何换算依据。第二类来自<strong>batch 与并发配比不同</strong>：高 batch 低并发与低 batch 高并发可以报告相同的吞吐，但尾部延迟与显存占用完全不同，前者在长尾负载下更易触发批完成时间膨胀。第三类来自<strong>指标定义漂移</strong>：把“生成阶段吞吐”与“端到端有效样本产出”混用，会把过滤阶段的损失藏进分子。</p>\n<ul>\n<li>看到吞吐提升时，先问 batch 与并发是否同口径，再看尾部延迟是否被牺牲。</li>\n<li>看到延迟下降时，先问是否换了精度档位，NVFP4 采样稳定性未验证前不能与 FP8 数字并列。</li>\n<li>看到显存节省时，先问 KV 复用是否改变了前缀共享粒度，粒度变化会让显存曲线非线性。</li>\n<li>看到方法改进更稳定的结论时，先问过滤阈值是否随任务重调，论文明确迁移到其他任务需重新验证。</li>\n</ul>\n<p>工程判断上，论文的扩展性结论适合做<strong>优先级排序</strong>：在同等算力预算下，先投入过滤策略与批调度，再考虑扩大模型或数据规模。但这个排序不构成容量数字。容量规划仍需在自己的 Blackwell 档位上，用二维 batch/并发网格测出 Yield 曲线，并把长尾监控纳入常规指标。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-49\">四十九 · 失败模式的口径归因：论文缺的定量部分怎么补</h3>\n<p>论文明确指出长尾样本与奖励评估耦合的失败模式缺少定量分析，这意味着诊断不能依赖论文的结论，必须自建口径。可操作的做法是把批完成时间分解为生成段与评估段两部分，分别记录尾部延迟分位数，再与过滤通过率联立。若生成段尾部延迟高而评估段正常，瓶颈在采样与批调度；若评估段尾部延迟随输入长度方差上升，瓶颈在前缀共享与 KV 复用粒度；若两段都正常但 Yield 低，瓶颈在过滤阈值与样本质量。</p>\n<p>另一个口径缺口是权重同步点。异步流水线中权重同步决定样本新鲜度与 off-policy 程度，论文只给出定性判断，未给出同步频率与吞吐的定量关系。工程上应把同步间隔作为一个独立维度记录，因为它会改变有效样本产出率的分母：同步越频繁，单位时间内可用于生成的算力越少，Yield 的分母被抬高。</p>\n<p>最后落在具体机制上：把论文的扩展性结论接入容量规划时，唯一可靠的接口是<strong>把“方法改进优先于堆规模”翻译成调度器的优先级权重</strong>——在批调度中给过滤策略与 KV 复用分配更高的优化预算，同时用尾部延迟分位数与批完成率作为硬约束，而不是用论文的趋势线去外推绝对吞吐。硬件档位、精度稳定性与过滤阈值的联合验证，才是这套结论在 Blackwell 上落地的实际边界。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-50\">五十 · 口径决定结论：这套扩展性结论在什么条件下失效</h3>\n<p>把论文的三线结论搬进容量规划前，先要承认它缺一层换算：材料未给出硬件档位、并行拓扑与量化方案，因此“方法改进更稳定”只能在相对意义上读，不能直接折算成 B200 上的 tokens/s 或 GB200 NVL72 机柜的功耗预算。可比性取决于四个口径是否对齐——模型规模与精度路径（FP8 还是 NVFP4 采样）、批大小与并发上限、奖励评估是否共享前缀 KV、以及指标取的是平均吞吐还是尾部完成时间。任一错位，跨方案的数字就不可比：批大小翻倍带来的吞吐提升往往以尾部延迟为代价，而前缀 KV 复用带来的收益在变长输入分布下会被稀释。工程上应先固定口径再比较，而不是先比数字再解释口径。</p>\n<p>长尾是这套流程的主要失效面。设批内第 i 条样本生成长度为 $L_i$，批完成时间由 $\\max_i L_i$ 决定而非 $\\sum_i L_i$，于是批吞吐近似为</p>\n<div class=\"formula\">$$\\text{Throughput}_{\\text{batch}}\\approx \\frac{B}{\\max_i L_i}\\quad\\text{而非}\\quad\\frac{B}{\\frac{1}{B}\\sum_i L_i}$$</div>\n<p>少数超长样本把整批拖到尾部，奖励评估段又因变长输入二次放大这一效应。因此监控必须同时看尾部延迟与批完成率，单看平均 TPOT 会掩盖瓶颈。过滤阈值同理：阈值抬高提升偏好对质量，却直接压低有效样本产出率，单位算力吞吐下降，这是方法层面“稳定提升”结论的边界条件。</p>\n<p>还有两处不可比需要单独标注。其一，异步流水线的权重同步点决定样本新鲜度与 off-policy 程度，同步越频繁则新鲜度越高但流水线气泡越多，不同同步策略下的吞吐数字不具可比性。其二，材料未给出 NVFP4 等低精度采样下的稳定性讨论，采样分布偏移会改变长尾形状，进而改变上式的分母。迁移到新任务时，方法层面的稳定性结论需重新验证，不能默认沿用。</p>\n<table class=\"mini\"><thead><tr><th>口径项</th><th>可比前提</th><th>错位后果</th></tr></thead><tbody><tr><td>批大小/并发</td><td>同一尾部延迟约束</td><td>吞吐虚高、SLO 不达标</td></tr><tr><td>前缀 KV 复用</td><td>同一输入长度分布</td><td>奖励评估吞吐被高估</td></tr><tr><td>过滤阈值</td><td>同一有效样本定义</td><td>质量与吞吐混淆</td></tr><tr><td>权重同步频率</td><td>同一 off-policy 上限</td><td>新鲜度收益无法归因</td></tr></tbody></table>\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-51\">五十一 · 迁移的第一道坎：奖励评估的变长输入与前缀复用假设</h3>\n<p>把本套推理方案搬到另一个模型或领域，最先失效的不是生成端，而是奖励评估端。论文的流程里，奖励模型或验证器接收的是变长候选回复，需要前缀共享与KV复用来摊薄重复计算。这个假设在工程上隐含两件事：其一，同一提示词下的多条候选回复共享足够长的前缀，复用才有收益；其二，奖励模型的前缀结构与策略模型的前缀结构可对齐，KV块能被同一套分页管理。迁到新领域时，若候选回复的构造方式从“同提示多采样”变成“跨提示对比”或“多轮拼接”，前缀共享率会骤降。设单条候选的评估成本为 $c_{\\text{eval}} = c_{\\text{pre}} + L\\cdot c_{\\text{dec}}$，其中 $c_{\\text{pre}}$ 为前缀计算成本、$L$ 为回复长度、$c_{\\text{dec}}$ 为逐token成本；当共享前缀长度 $P$ 从接近提示长度退化到接近零时，整批评估成本从 $N\\cdot c_{\\text{pre}}(P) + \\sum L_i c_{\\text{dec}}$ 退化为 $N\\cdot c_{\\text{pre}}(0) + \\sum L_i c_{\\text{dec}}$，前缀项随候选数线性膨胀。在Blackwell上这意味着奖励模型的KV cache占用与HBM带宽压力同步上升，原本靠复用压住的显存水位被顶穿，批大小被迫下调，吞吐随之塌陷。判断标准很直接：迁移前先测同一提示下候选回复的平均共享前缀占比，低于阈值就不要指望复用收益，应改为把奖励评估拆成独立的小批流水，用更细的批调度换回显存。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-52\">五十二 · 过滤阈值的迁移代价：有效样本产出率与吞吐的再平衡</h3>\n<p>论文的核心判断之一是方法层面的过滤策略在同等算力下比堆数据堆模型更稳定，但这条结论绑定了具体的过滤阈值与偏好数据构造方式。迁到新领域时，阈值的语义会漂移：在一个奖励模型打分分布集中的任务里，阈值切掉的是低质量尾部；换到一个打分分布弥散、噪声更高的领域，同一阈值切掉的可能是有信息量的中段样本，有效样本产出率 $\\eta = N_{\\text{keep}}/N_{\\text{gen}}$ 骤降。rollout引擎的单位算力有效产出可写成 $\\text{Goodput} = \\dfrac{\\eta\\cdot N_{\\text{gen}}}{T_{\\text{batch}}}$，其中 $T_{\\text{batch}}$ 由长尾样本决定。阈值抬高会压低 $\\eta$ 但提升样本质量，阈值降低则相反；迁移时若不同步重标定阈值，$\\eta$ 与 $T_{\\text{batch}}$ 会同时恶化，Goodput 双向受损。工程上的做法是把阈值当作可在线观测的参数而非固定常数：在奖励评估段记录打分直方图，按分位数而非绝对分数设阈值，使 $\\eta$ 在迁移后维持在可控区间。代价是奖励评估段要多一次轻量统计聚合，占用少量SM周期与一次全局归约通信，但在NVL72的NVLink 5域内这次归约的代价远小于阈值失配带来的吞吐损失。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-53\">五十三 · 长尾分布跨领域漂移：尾部延迟监控不能照搬</h3>\n<p>论文明确指出生成长度呈长尾分布，少数超长样本拖慢整批完成时间，且长尾在生成与评估两段都构成瓶颈。这套方案迁到新领域时，长尾的形状会变，而按旧领域标定的尾部延迟告警阈值会失效。设批完成时间 $T_{\\text{batch}} = \\max_i (t_{\\text{gen},i} + t_{\\text{eval},i})$，长尾样本的 $t_{\\text{gen}}$ 由生成长度决定，$t_{\\text{eval}}$ 由变长输入的前缀复用率决定。迁到一个回复更短但评估更重的领域（例如需要多字段校验的结构化输出），瓶颈会从生成段平移到评估段，原本针对生成尾部的监控指标失去解释力。更麻烦的是连续批处理下，超长样本占住一个批槽位不放，新请求无法填入，形成队头阻塞；此时吞吐的上限由 $\\frac{B}{T_{\\text{tail}}}$ 而非平均完成时间决定，$B$ 为批槽位数。迁移判断：先在新领域采样一批真实请求，测出生成与评估两段各自的P99与P50比值，比值超过阈值就把该段独立拆批，避免两段长尾叠加。这一步不需要新硬件，但需要在调度器里加分段计时探针，代价是每批多一次时间戳写入与聚合。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-54\">五十四 · 规模上限：收益递减曲线在rollout侧的映射</h3>\n<p>论文的扩展性结论是数据、模型、方法三条线均存在收益递减，方法改进在同等算力下更稳定。把这条结论搬到容量规划上，要区分两种规模：生成批量规模与模型规模。生成批量 $N$ 增大时，吞吐先升后平，因为奖励评估段的前缀复用率随批增大而下降、长尾样本的占比随批增大而上升，单位样本成本 $c(N) = \\dfrac{C_{\\text{fixed}}}{N} + c_{\\text{var}}(N)$ 中的 $c_{\\text{var}}$ 不再恒定。模型规模增大时，单token生成成本上升，但若方法层面的过滤策略不变，有效样本产出率 $\\eta$ 未必同步提升，于是单位算力有效产出可能不升反降。这就是规模上限的工程含义：不是算力不够，而是 $\\eta$ 与复用率随规模变化的斜率把边际收益吃掉。判断方法是在目标Blackwell档位上做小规模扫描，固定方法配置，只变批量与模型档位，测 Goodput 曲线拐点；拐点之前的区间才是可承诺SLO的容量区间。材料未给出具体硬件档位与并行拓扑，因此这条曲线必须在实际部署档位上实测，不能从论文结论直接外推。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-55\">五十五 · 低精度采样与异步流水线：迁移时必须单独验证的两处</h3>\n<p>材料明确未给出NVFP4等低精度采样下的稳定性讨论，也未给出并行切分与量化方案。迁到Blackwell部署时，这两处是方案能否落地的硬边界。策略模型批量生成若采用低精度采样，采样分布的尾部会被量化误差扰动，长尾样本的长度分布随之改变，进而影响 $T_{\\text{batch}}$ 与尾部延迟监控的基线；这不是精度问题而是调度问题——尾部分布变了，按旧分布设的批超时与抢占策略会误判。异步流水线方面，权重同步点决定样本新鲜度与off-policy程度，迁移到新领域时若过滤策略变更导致样本产出节奏变化，同步点与产出节奏的相位关系会漂移，off-policy程度上升，训练稳定性下降。工程判断：低精度采样先在目标档位上做小批稳定性对照，观察长尾长度分布是否偏移；异步流水线则把同步点与过滤阈值解耦，按产出率而非固定步数触发同步。两处验证都需要额外的观测开销，但比起迁移后吞吐与稳定性同时失守，这笔开销是必要成本。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-56\">五十六 · 哪里不适用：三条明确的边界</h3>\n<p>这套方案的适用边界可以收敛为三条。第一，当候选回复之间几乎不共享前缀时，前缀复用与KV复用的整套优化失效，奖励评估退化为逐条独立计算，方案的核心吞吐假设不成立，应改用无复用的独立评估流水。第二，当过滤阈值无法用分位数稳定标定、打分分布随请求类型剧烈漂移时，方法层面改进的稳定性结论不再成立，此时堆数据或堆模型规模的边际收益反而更可预测，方案的方法优先判断需要反转。第三，当长尾样本占比高到批完成时间由尾部而非均值主导、且无法分段拆批时，连续批处理的槽位利用率被尾部锁死，吞吐上限由尾部延迟而非算力决定，此时扩容硬件不解决问题，应先改调度结构。这三条边界都不是定性口号，而是可以在迁移前用共享前缀占比、打分分布漂移度、尾部与均值比值三个观测量判定的工程门槛；越过门槛再谈迁移，否则方案在新领域的收益会被结构性代价抵消。</p>\n\n<h3 id=\"paper-does-rlhf-scale-exploring-the-impact-2024-sec-57\">五十七 · 迁移不是复制：三条线各自的失效条件与算力换算缺口</h3>\n<p>把这篇论文的扩展性结论搬到另一套模型或领域时，最先失效的不是公式，而是“方法层改进更稳定”这一判断的适用前提。论文的方法线收益来自偏好数据构造与过滤策略，而过滤阈值直接决定有效样本产出率：阈值抬高会剔除低分与高噪声样本，提升单位样本质量，却同时压低单位算力下的吞吐。迁移到新领域时，奖励模型的打分分布会整体偏移，原先在源领域标定的阈值不再对应同一分位，过滤后剩下的偏好对可能既少又有偏。工程上的判断是：阈值必须按目标领域的奖励分数分布重新标定，并以“有效偏好对产出率”而非“生成条数”作为容量指标；若只搬调度代码不搬标定流程，rollout 引擎会在吞吐达标的同时产出无法支撑策略更新的数据。</p>\n<p>规模上限出现在生成与评估的耦合处，而非单段算力。生成长度呈长尾分布，少数超长样本拖慢整批完成时间；奖励评估阶段输入变长，需要前缀共享与 KV 复用，否则重复计算显著降低吞吐。批越大吞吐越高，但尾部延迟风险同步上升，批完成时间由最慢样本决定，可写成近似关系：</p>\n<div class=\"formula\">$$T_{\\text{batch}}\\approx \\max_{i\\in \\text{batch}}\\left(L_i^{\\text{gen}}\\,/\\,\\dot n_{\\text{gen}}+L_i^{\\text{rm}}\\,/\\,\\dot n_{\\text{rm}}\\right)$$</div>\n<p>其中生成长度与评估长度的长尾项主导上界。这意味着单纯扩大批量或提升算力档位，收益会被尾部样本吞掉；论文所说“方法层改进优于堆叠规模”，在系统层面就对应把预算投向过滤与调度，而不是投向更大的批。迁移到长输出领域（如多步推理、长文档生成）时，长尾更重，这一上限会更早到来。</p>\n<p>第二类边界是异步流水线的样本新鲜度。权重同步点决定样本新鲜度，进而影响 off-policy 程度与训练稳定性；方法层的过滤策略若依赖较新的策略分布，同步间隔拉长会使过滤判据与当前策略错位。迁移到更新频率更高的场景时，需要把同步间隔纳入容量规划，而不是只优化单次 rollout 的吞吐。</p>\n<p>最后是算力换算的硬缺口。材料未给出具体硬件档位、并行拓扑与量化方案，因此论文结论无法直接换算为 Blackwell 部署下的吞吐与显存代价；NVFP4 等低精度采样下的稳定性也需单独验证。可用下表做迁移前的检查项，而不是把结论当口号：</p>\n<table class=\"mini\"><thead><tr><th>迁移维度</th><th>需重标定的对象</th><th>失效信号</th></tr></thead><tbody><tr><td>领域奖励分布</td><td>过滤阈值与分位</td><td>有效偏好对产出率骤降</td></tr><tr><td>输出长度形态</td><td>批大小与尾部延迟预算</td><td>批完成率下降、尾延迟抬升</td></tr><tr><td>更新节奏</td><td>权重同步间隔</td><td>off-policy 程度上升</td></tr><tr><td>精度方案</td><td>采样与评估数值路径</td><td>打分分布漂移、需单独验证</td></tr></tbody></table>\n<p>工程判断落在监控口径上：迁移后应同时观测尾部延迟、批完成率与有效样本产出率三项，任一恶化即说明该领域的扩展曲线已偏离论文结论的适用区间，此时应回退到方法层调参而非加算力。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Does RLHF Scale? Exploring</text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\"> the Impacts …</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2024 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Does RLHF Scale? Explor… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称与规模</td></tr><tr><td>基线</td><td>材料未给出具体基线方法</td></tr><tr><td>主要结果</td><td>论文报告RLHF的扩展性在数据、模型与方法三个维度上均存在收益递减，方法层…</td></tr><tr><td>消融</td><td>材料未给出具体的消融实验设置与数字，仅提及数据、模型与方法三条线的相对贡献…</td></tr><tr><td>局限</td><td>论文未给出具体的硬件档位、并行拓扑与量化方案，因此无法直接换算为Black…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-does-rlhf-scale-exploring-the-impact-2024 · 共 9 个片段</p>\n";break;}}})();
